private typealias E = EvidenceSeed

/// Alternate tellings, batch I: the same cases, played out another way.
extension StoryVariants {
    static let variantsI: [CaseTemplate] = [boatRampCoolerV1, bathSaltsPorchV1, twoOverdoseDealerV1, alteredScriptsV1, fakeGameWardenV1, blueLightsRoadStopsV1, windowFilmingNeighborV1, firedWorkerTextsV1, hospitalBombCallV1, trailerToddlerNeglectV1, babysitterInfantInjuryV1, poolMotherLeftV1, runawayRideV1, benefitCardCashV1, therapyBillingGhostV1, liftingBackClaimV1, stormRepairAdvanceV1, sickPuppiesPapersV1, executorEstateSalesV1, tuitionCheckBookkeeperV1, unionTreasurerChecksV1, campaignTreasurerCarV1, foodBankVacationsV1, vendingRouteSkimV1]

    static let boatRampCoolerV1 = SmallCases.make(
        key: "story.boatRampCooler",
        category: .drugs,
        headlines: ["Camper Cooler at Lake Campground Holds Cocaine Under Ice", "K-9 Alerts at the Pavilion"],
        law: "traffickingCocaine",
        threshold: 8,
        spec: "Trafficked in cocaine by possession of 28 grams or more, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A K-9 alerted on a camper's cooler at a lake campground on {DATE}. 450 grams of cocaine sat under ice. The camper registered to {D}. {DL} says a guest brought it.",
        state: [E(.forensic, 3, "Lab Report", "450 grams of cocaine."), E(.physical, 3, "Cooler", "Cocaine under ice.", .search), E(.document, 2, "Registration", "Camper registered to {D}.")],
        defense: [E(.statement, 1, "Guest", "{DL} says a guest brought the cooler.")],
        role: "Deputy",
        exam: [.direct("Why did your K-9 team go to the lake campground on {DATE}?", "\"We were doing a routine patrol of the sites. My dog alerted on a camper's cooler as we walked the loop, so I stopped to look.\""), .direct("Whose camper was it?", "\"The registration ties it to {D}. The paperwork was in the glove box and the plate matched the site reservation.\""), .direct("What did you find in the cooler?", "\"Under a layer of ice, wrapped in bags, was cocaine. The lab later confirmed 450 grams, which is far more than a personal amount.\""), .direct("How was the cocaine packaged and hidden?", "\"It was bagged and pushed to the bottom of the cooler beneath ice and drinks, where someone checking for food would not see it.\""), .direct("Where was {DL} when you searched?", "\"{D.He} was near the camper. I explained the alert, and the search of the cooler followed.\""), .direct("What did {DL} tell you about the cooler?", "\"{D.He} said a guest had brought it and that {D.he} had not opened it. I wrote that down and asked for the guest's name.\""), .cross("Isn't a cooler something that gets carried in and out by different people at a campground?", "\"Yes, coolers move around a lot. That is why I looked at who rented the site and who the camper was registered to.\""), .cross("Did you see {DL} touch or open the cooler?", "\"No. By the time I reached the site the cooler was sitting by the camper. I did not watch anyone handle it.\""), .cross("Were fingerprints taken from the bags?", "\"I do not have a print result to give you. I cannot tell this jury whose hands packed the bags.\""), .cross("Was {DL} cooperative with you?", "\"Yes. {D.He} stayed put, answered my questions, and did not try to leave or interfere with the dog.\""), .cross("Did you find scales, cash, or sales records in the camper?", "\"No. The cocaine and the cooler were the main items. I did not recover scales or a ledger.\"")],
        defenseRole: "Guest",
        defenseExam: [.direct("How do you know {DL}?", "\"We have been friends for years. I have camped with {D} before and I was invited to this lake weekend.\""), .direct("Did you bring something to the site?", "\"Yes. I brought a cooler with supplies for the trip and set it by the camper.\""), .direct("Did you tell {DL} what was in it?", "\"No. I said it was my cooler for the weekend. {D.He} was busy setting up and did not ask.\""), .direct("Did {DL} open it in front of you?", "\"Not that I saw. {D.He} went about the campsite and left the cooler in the shade by the door.\""), .direct("How did {DL} react when the dog alerted?", "\"Shocked, as far as I could tell. {D.He} stepped back and said the cooler was mine.\""), .direct("Why did you not step forward that day?", "\"I was frightened and I left the site. I have thought about that choice since and I am here now.\""), .cross("The cocaine was in the cooler you brought, wasn't it?", "\"I am not going to say anything that incriminates me. I brought a cooler. That is all I will say.\""), .cross("Whose idea was the weekend?", "\"It was {D.his} trip. I joined because I was invited. {D.He} planned the sites and the food.\""), .cross("You did not tell {DL} the contents, did you?", "\"No. I did not discuss the contents with anyone. That was my choice.\""), .cross("You left the campground after the alert, didn't you?", "\"Yes. I left in a panic. I should have stayed and spoken to the deputy that day.\""), .cross("You and {DL} are close friends, aren't you?", "\"Yes. Being close is exactly why I would not want {DF} blamed for something that was mine.\"")],
        theory: ("{D} trafficked cocaine.", "A guest."),
        allocution: "\"That camper is registered to me, and I had the site for the weekend, and I invited a few people to stay near it. A guest unloaded that cooler while I was setting up. I assumed it held drinks and food. I should have looked. I'm sorry for putting myself and others at risk.\"",
        truths: ("{DL} had texted a number about a delivery.", "The guest's name is in {DL}'s phone."),
        defendant: [.direct("Whose camper was at the campground?", "\"Mine. It is registered in my name, and I had the site for the weekend. I invited a few people to stay near it.\""), .direct("Who brought the cooler to your site?", "\"I was setting up and did not watch the guest unload. I assumed it held drinks and food.\""), .direct("Did you ever open that cooler?", "\"No. I had my own food in another one. This one stayed beside the camper, and I never lifted the lid.\""), .direct("What did you think when the dog alerted?", "\"I was stunned. I had no idea anything like that was inside. I told the deputy right away it belonged to a guest.\""), .direct("Have you ever possessed or sold cocaine?", "\"No. I do not use it and I do not sell it. Nothing like that has ever been in my camper.\""), .direct("Why did you not leave when you saw the deputy?", "\"I had nothing to hide. I stayed, answered questions, and gave the guest's name as best I could.\""), .cross("The camper is registered to you, correct?", "\"Yes, it is. I accept responsibility for the camper, but I did not know what a guest put in a cooler.\""), .cross("You invited the guest, didn't you?", "\"I trusted the guest like any friend, and I did not search the guest's belongings.\""), .cross("Four hundred fifty grams is a lot to bring to a weekend trip, isn't it?", "\"It is a huge amount, which is why I am certain it was not mine. Nobody told me it was in the camper.\""), .cross("You were nearby the whole weekend, weren't you?", "\"Mostly. But I was fishing and cooking, not watching who carried what to the shaded side of the camper.\""), .cross("You cannot make that guest appear in this courtroom, can you?", "\"I can name the guest and a friend can speak for the guest. I know it sounds convenient, but it is what happened.\"")],
        openings: ("A police dog alerted on a cooler at a lake campground, and under the ice sat 450 grams of cocaine. The camper is registered to {D}, and the State will show the lab result, the cooler, and who held the site.", "Close the cooler and open your eyes to who actually brought it. A guest carried it in, {D} never lifted the lid, and the guest will tell you so."),
        closings: ("Four hundred fifty grams of cocaine sat beneath ice beside a camper registered to {D}, on a site {DL} rented. People in control of a space answer for what is hidden in it.", "A guest brought the cooler and {D} never opened it. No print, no scale, no cash ties {DL} to those bags, and without knowledge there is no possession."),
        timeline: [(0, "Dawn: the campground."), (0, "6:30 a.m.: K-9 alert."), (0, "7 a.m.: search."), (0, "8 a.m.: arrest.")],
        identified: "A K-9 and a search.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["searchSeizure", "mistakeOfFact"])

    static let bathSaltsPorchV1 = SmallCases.make(
        key: "story.bathSaltsPorch",
        category: .drugs,
        headlines: ["Man Sells Synthetic Powder From Garage Fridge", "Undercover Buy Recorded"],
        law: "saleSchedII",
        threshold: 7,
        spec: "Sold a Schedule I controlled substance, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "An undercover deputy bought synthetic powder from {D}'s garage fridge on {DATE}. Video recorded the exchange. {DL} says {D.he} thought it was plant food.",
        state: [E(.video, 3, "Buy Video", "{D} hands over a bag for $60."), E(.forensic, 3, "Lab Report", "A synthetic cathinone."), E(.document, 2, "Buy Money", "Marked bills recovered.")],
        defense: [E(.statement, 1, "Plant Food", "{DL} says {D.he} thought it was plant food.")],
        role: "Undercover deputy",
        exam: [.direct("What was your assignment on {DATE}?", "\"I was working undercover, buying small quantities of synthetic powders that were being sold from homes in the area.\""), .direct("Where did the buy take place?", "\"At {D}'s garage. {D.He} opened the garage fridge, took out a bag, and handed it to me for $60 while my body camera ran.\""), .direct("What did the video capture?", "\"It captures the whole exchange: the conversation, the fridge door opening, the bag, and the cash changing hands.\""), .direct("What was in the bag?", "\"The lab identified a synthetic cathinone, which is a controlled substance, not a garden product.\""), .direct("What happened to the money you paid?", "\"The bills were marked, and deputies recovered the marked bills afterward as part of the investigation.\""), .direct("What did {DL} say about the powder?", "\"When I asked what it was, {D.he} gave me a casual answer about it being plant food. I noted it exactly.\""), .cross("Did {DL} say anything about getting high or using it on people?", "\"No. {D.He} did not describe any drug effect to me. I only heard the plant food remark.\""), .cross("Did the bag carry a label?", "\"It was a plain bag with no brand that I recall. I do not have a label to read to you.\""), .cross("How many transactions did you make with {DL}?", "\"This was the one I personally made. I cannot speak to other sales from my own knowledge.\""), .cross("Did {DL} try to hide the sale?", "\"Not particularly. The garage was open and the sale was casual and quick.\""), .cross("Did you test the powder yourself at the scene?", "\"No. I bagged it and sent it to the lab. I rely on the lab report for what it was.\"")],
        defenseRole: "Supplier clerk",
        defenseExam: [.direct("What do you do at your supply business?", "\"I work as a clerk at a supplier that sells garden and bath products, including bags of mineral powders.\""), .direct("Did {DL} buy from you?", "\"Yes. {D} bought bags of powder labeled for plants. I have the invoice.\""), .direct("What did the label say?", "\"It said plant food. That is how we received it and how we sold it.\""), .direct("Was there a warning about ingesting it?", "\"No warning that I recall on those bags. We sold it as plant food and nothing else.\""), .direct("What kind of customer was {DL}?", "\"Ordinary and polite. {D.He} asked normal questions about what the powder did for plants.\""), .direct("Did you ever see {DL} sell it to others?", "\"No. I only know what {D.he} bought from us. What {D.he} did afterward I cannot say.\""), .cross("Is that product safe to swallow?", "\"No. It was sold for plants, and no one should ingest it.\""), .cross("Did you know what the powder actually contained?", "\"I did not test it. I relied on the supplier's label like everyone else.\""), .cross("Would a plant food normally contain a controlled substance?", "\"No. It should not. If it did, that is a serious problem with where it came from.\""), .cross("Did {DL} buy many bags?", "\"A few. I would have to check the invoice for the exact number.\""), .cross("Did you ever sell this product to anyone who asked about getting high?", "\"No. If a customer had asked that, I would have refused.\"")],
        theory: ("{D} sold a drug.", "Plant food."),
        allocution: "\"I bought a box of small bags labeled plant food for my tomatoes, and I sold a few to neighbors out of the garage fridge. I never knew they were anything else. I'm sorry for the trouble, and I'll accept whatever the court recommends.\"",
        truths: ("{DL} sold six bags that week.", "The label said plant food."),
        defendant: [.direct("What did you think you were selling?", "\"Plant food. It was labeled that way on the box I kept in the garage fridge, and I used it on my garden.\""), .direct("Where did you get it?", "\"From a supplier. I bought a box of small bags for my own tomatoes and sold a few to neighbors.\""), .direct("Why did you keep it in a fridge?", "\"The directions said to keep it cool. I kept my seeds and fertilizer in the garage fridge for that reason.\""), .direct("What did you tell the buyer?", "\"I said it was plant food. That is all I knew and all I said. I never said it would get anyone high.\""), .direct("Did you know it was a controlled substance?", "\"No. I would never sell something like that. I believed the label and the supplier.\""), .direct("How did you feel when you learned the result?", "\"Sick. I felt I had been fooled by the label and I was embarrassed that I had put it in people's hands.\""), .cross("You took $60 for a small bag, didn't you?", "\"Yes. Plant food can be pricey. I thought it was a fair price for a specialty product.\""), .cross("Who asked you to sell plant food to a stranger?", "\"No one asked. The buyer came to my garage and wanted a bag. I sold what I thought was fertilizer.\""), .cross("You kept it in a fridge in your garage, not in the garden shed, correct?", "\"Correct. The directions said cool. I know how that sounds, but I followed what I read.\""), .cross("You never tested it, did you?", "\"No. I never tested it. I trusted the package and I should have been more careful.\""), .cross("Selling bags out of a garage fridge is unusual for plant food, isn't it?", "\"It may be unusual. I sold a few to friends and neighbors, and I never gave it a second thought.\"")],
        openings: ("An undercover deputy bought a bag of synthetic powder from {D}'s garage fridge for $60, and a camera recorded every moment. The lab calls it a synthetic cathinone, and the State will show the video, the report, and the marked bills.", "Plant food. That is the word on the package {D} bought, and the supplier's own clerk will tell you the label said exactly that. {D.He} sold what {D.he} believed was fertilizer."),
        closings: ("A bag handed over for $60, a lab report naming a controlled substance, and marked bills recovered. {D} sold what the lab says is illegal, and the video proves who sold it.", "The label said plant food, and the supplier confirms it. The State has not proved {D} knew the powder was a controlled substance, and a mistaken belief about a product is not a crime."),
        timeline: [(-3, "Complaints."), (0, "4 p.m.: the buy."), (0, "4:10 p.m.: field test."), (1, "Arrest.")],
        identified: "A buy video.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["mistakeOfFact", "entrapment"],
        genders: ["D": .male])

    static let twoOverdoseDealerV1 = SmallCases.make(
        key: "story.twoOverdoseDealer",
        category: .drugs,
        headlines: ["Friends Found Dead Hours Apart With Stamped Pills Traced to a Home Pill Press", "Online Order for a Tablet Press Ties Batch to Defendant"],
        law: "deathByDistribution",
        threshold: 8,
        spec: "Unlawfully sold a controlled substance that caused the death of {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} and a friend died within hours of each other on {DATE} after taking blue tablets stamped 'M30'. Toxicology found fentanyl. Messages showed {V} buying the pills from {D} the night before. Investigators found a tablet press, die stamps and binder in {DL}'s garage. A shipping record showed {DL} ordered the press three months earlier. {DL} says {D.he} only passed along pills a friend gave {D.him}.",
        state: [E(.forensic, 3, "Toxicology", "Fentanyl in both who died."), E(.digital, 3, "Messages", "{V} buys pills from {D}."), E(.physical, 2, "Pill Press", "A tablet press and 'M30' die in {D}'s garage."), E(.document, 1, "Shipping Record", "Press ordered three months earlier.")],
        defense: [E(.statement, 1, "Passed Along", "{DL} says {D.he} only passed along pills."), E(.statement, 1, "Friend's Supply", "{DL} says a friend made the pills.")],
        role: "Overdose investigator",
        exam: [.direct("What caused the two deaths?", "\"{V} and a friend died within hours of each other after taking blue tablets stamped 'M30'. Toxicology found fentanyl in both.\""), .direct("How was {D} connected to the pills?", "\"Messages show {V} buying the pills from {D} the night before. {DL} sold them to {V}.\""), .direct("What did you find in the defendant's garage?", "\"A tablet press and an 'M30' die, with binder. A shipping record shows {DL} ordered the press three months earlier.\""), .direct("Please explain your role as an overdose investigator.", "\"I investigate deaths from drug overdoses for the county. I visit scenes, review toxicology reports, and look for the source of the pills.\""), .direct("What did you learn about the night before the deaths?", "\"Messages show {V} arranged to buy blue tablets from {DL}. The tablets were stamped M30, and {V} and a friend took them that night.\""), .direct("What did the toxicology show?", "\"Fentanyl was found in both people who died. The amounts were enough to cause death, and no other substance accounted for the deaths.\""), .cross("{D} says {D.he} only passed along pills a friend gave {D.him}, doesn't {D.he}?", "\"Yes. That is what {D.he} says. I do not have the friend's name.\""), .cross("Could a person press fentanyl pills without any training?", "\"It takes some skill. But it can be done with the right equipment.\""), .cross("Did anyone see the defendant press pills?", "\"No. No one saw that. We have the equipment and the order.\""), .cross("Did anyone test the pills that the defendant supposedly sold?", "\"We tested the pills found at the scene. We did not test every pill {DL} ever had, and I cannot say what was in every batch.\""), .cross("Did {D} ever say that the pills came from a friend?", "\"Yes. {DL} said a friend made the pills. We did not find the friend, but we did find a press and die in {DL}'s own garage.\"")],
        theory: ("{D} pressed and sold fentanyl pills that killed two people.", "A seller who passed along pills."),
        allocution: "\"I ordered that press for a hobby project, and I never used it for pills. I told {V} the pills were clean because I believed it, and I didn't know there was fentanyl in them. I'm sorry for both families' loss. I'm sorry for putting myself and others at risk.\"",
        truths: ("{DL} had ordered binder and dies in the same month as the press.", "{DL} told {V} the pills were 'clean'."),
        defendant: [.direct("Why was a tablet press in your garage?", "\"I ordered it for a hobby project. I never used it for pills.\""), .direct("What did you tell {V} about the pills?", "\"I told {V.him} they were clean. I believed it. I did not know they had fentanyl.\""), .direct("Tell us how you came to know {V}.", "\"We knew each other for years and often hung out. I tried to help when {V} was struggling, and I considered {V} a real friend.\""), .direct("What was your role in getting pills to {V}?", "\"I passed along pills that a friend gave me. I did not press them or make them, and I told {V} they were clean.\""), .direct("What else did you order with it?", "\"A binder and some empty capsules, which I thought I needed for the hobby project. I never used any of it.\""), .direct("What did you say to {V} about the pills the night before?", "\"That they were clean and would not hurt anyone. I believed that because I trusted the supplier, and I never tested them.\""), .cross("You ordered binder and dies in the same month as the press, didn't you?", "\"I did. They were for the project. I know how that looks now.\""), .cross("An 'M30' die in your garage matches the stamp on the pills, doesn't it?", "\"It matches. I did not stamp them. I never used it.\""), .cross("Two people are dead. Do you feel responsible?", "\"I feel terrible. I wish I had never said the pills were clean.\""), .cross("You told {V} the pills were clean, didn't you?", "\"Yes. I believed it, but I never tested them. I now know I was wrong, and I will think about it for the rest of my life.\""), .cross("You gave {V} no way to check what was in those pills, did you?", "\"No. I only said they were clean, and I had no way to test them myself. I should never have said it.\"")],
        openings: ("{V} and a friend died within hours of each other after taking blue tablets stamped 'M30' that held fentanyl. Messages show {V} buying them from {D}, and a pill press and an 'M30' die were found in {DL}'s garage.", "Listen for the defense evidence, which will show that {D} only passed along pills a friend gave {DL}, that the press was for a hobby, and that {DL} believed the pills were clean."),
        closings: ("Two dead, fentanyl in both, messages showing {V} buying from {D}, and a pill press with an 'M30' die in {DL}'s garage. The evidence points to {DL}.", "A friend's pills passed along and a press that was never used. The State must prove {D} made or knowingly sold the pills that killed two people."),
        timeline: [(-90, "{D} orders the press."), (-1, "{V} buys the pills."), (0, "Two friends are found dead."), (1, "Toxicology reports fentanyl."), (4, "The garage is searched.")],
        identified: "A pill press.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let alteredScriptsV1 = SmallCases.make(
        key: "story.alteredScripts",
        category: .whiteCollar,
        headlines: ["Cleaner Took Pad From Clinic Supply Closet, Wrote Prescriptions at Four Pharmacies", "Pad Serial Numbers and Janitor Camera Line Up"],
        law: "prescriptionFraud",
        threshold: 7,
        spec: "Obtained controlled substances by forging and altering prescriptions, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A clinic noticed a prescription pad missing from a supply closet. Four pharmacies reported prescriptions with the clinic's header, a doctor's name and quantities that were too large. The pad's serial numbers matched the missing pad. A closet camera showed {D}, an evening cleaner, taking the pad. {DL} says {D.he} found the pad in a trash bin and did not know what it was.",
        state: [E(.physical, 3, "Prescriptions", "Four forged prescriptions matching the missing pad."), E(.video, 3, "Closet Camera", "{D} takes the pad."), E(.statement, 2, "Pharmacist", "{D} presented the prescriptions."), E(.document, 1, "Pad Serial Numbers", "Match the missing pad.")],
        defense: [E(.statement, 1, "Trash Bin", "{DL} says the pad was in a trash bin."), E(.statement, 1, "Never Used", "{DL} says {D.he} never filled any.")],
        role: "Pharmacist",
        exam: [.direct("How did the clinic's prescription pad come to your attention?", "\"Four pharmacies in our area, including mine, received prescriptions that had the clinic's header and a doctor's name but quantities that were far too large.\""), .direct("What was strange about the prescriptions?", "\"The quantities. A real prescription from that doctor would not have asked for so much, and the handwriting looked off.\""), .direct("What did you learn about the pad?", "\"The clinic reported a pad missing from a supply closet. The serial numbers on the pad matched the prescriptions presented to us.\""), .direct("Who presented the prescriptions to you?", "\"{D}. I recognized the face from our counter. {D.He} handed over a prescription and waited for it to be filled.\""), .direct("What does the closet camera show?", "\"{DL}, an evening cleaner, taking the pad from the closet. It is clear enough to see the pad being lifted and carried off.\""), .direct("What did you do when you doubted the prescription?", "\"I called the clinic to verify, as we do for large quantities. They said the pad had been missing, and I declined to fill it.\""), .cross("Did {DL} act nervous when presenting the prescription?", "\"Not noticeably. {D.He} stood calmly and waited. I would not say anything stood out about the behavior.\""), .cross("Did you see {DL} write on any of the prescriptions?", "\"No. I only saw {DL} present them. I did not see who filled in the quantities.\""), .cross("Could someone else have handed {DL} the prescriptions?", "\"It is possible. I can only say who stood at my counter, not who wrote the paper.\""), .cross("Did {DL} leave anything with you besides the prescription?", "\"An ID, as requested. It matched the person at the counter.\""), .cross("Did you dispense any medication?", "\"No. I did not fill it once I called the clinic. Nothing left my pharmacy.\"")],
        theory: ("{D} forged prescriptions from a stolen pad.", "A cleaner who found a pad."),
        allocution: "\"I clean that clinic at night, and I found that pad in a trash bin while I was emptying cans. I picked it up without knowing what it was, and I should have told someone right away. I'm sorry for the trouble it caused.\"",
        truths: ("{DL} took the pad on a night the clinic's door was locked.", "{DL} presented the prescriptions at four pharmacies."),
        defendant: [.direct("What do you do at the clinic?", "\"I clean at night, an evening shift. I empty trash, mop floors, and restock supplies when asked.\""), .direct("Why did you take the pad from the closet?", "\"I did not take it. I found it in a trash bin while emptying cans. I picked it up and did not know what it was.\""), .direct("What did you think it was?", "\"A pad of paper someone had thrown out. I took it for notes. I did not look closely at the header.\""), .direct("Did you ever fill in a prescription?", "\"No. I never wrote on any of those pages. I did not know what a prescription pad was worth.\""), .direct("Why were you at pharmacies with prescriptions?", "\"I was not trying to fill anything illegal. I had a few pages with printing and I thought they were ordinary forms.\""), .direct("What did you do when the pharmacist called the clinic?", "\"I left. I was confused and embarrassed. I did not know why a pharmacist would doubt a form I had.\""), .cross("The camera shows you taking the pad from the closet, doesn't it?", "\"It shows me near the closet picking something up. I thought it was trash. I admit it looks bad.\""), .cross("You presented the prescriptions at four pharmacies, didn't you?", "\"Yes. I tried more than one because I thought they were just not being accepted for some technical reason.\""), .cross("The quantities were far too large, weren't they?", "\"I did not look at them. If I had read the quantity I would have known something was wrong.\""), .cross("You did not report finding a pad in the trash, did you?", "\"No. I should have told the clinic. I did not realize it mattered.\""), .cross("Every page carried the clinic's header, didn't it?", "\"Yes. I know that. I did not read it. I know how unbelievable that sounds.\"")],
        openings: ("A prescription pad vanished from a clinic supply closet, and soon four pharmacies saw prescriptions with the clinic's header, a doctor's name, and quantities far too large. A camera shows {D} lifting the pad, and the State will tie it all together.", "The pad was in a trash bin when {D} found it. {D.He} cleaned at night, picked up what looked like discarded paper, and never knew what it was. Listen for what the evidence leaves out."),
        closings: ("A pad taken from a closet on camera, serial numbers that match four forged prescriptions, and {D} at the counter handing them over. That is forgery and an attempt to obtain drugs.", "{D} found a pad in the trash and thought it was scrap. The State has not proved {DL} knew what it was or wrote a single quantity on those pages."),
        timeline: [(-14, "The pad goes missing."), (-7, "The first forged prescription."), (0, "A pharmacist calls the clinic."), (1, "The closet camera is reviewed."), (2, "{D} is identified.")],
        identified: "A pharmacist's call.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let fakeGameWardenV1 = SmallCases.make(
