        category: .publicOrder,
        headlines: ["Man Poses as Park Ranger to Collect Cash From Campers", "Badge Bought Online"],
        law: "impersonatingLEO",
        threshold: 6,
        spec: "Impersonated a law enforcement officer, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} wore a ranger-style uniform and a badge on {DATE} and collected 'camping fees' from campers. Park officials said no such ranger existed. {DL} says it was a costume.",
        state: [E(.statement, 3, "Camper", "'He showed a badge.'"), E(.physical, 3, "Badge", "A badge bought online.", .search), E(.document, 2, "Agency Letter", "No such officer.")],
        defense: [E(.statement, 1, "Costume", "{DL} says it was a costume.")],
        role: "Camper",
        exam: [.direct("What happened at your campsite on {DATE}?", "\"A person in a ranger-style uniform and a badge walked up to the camp and asked us for a camping fee, in cash.\""), .direct("What did {DL} look like?", "\"A tan uniform, a patch, a badge, and a clipboard. It looked like what park staff wear, so I never doubted it.\""), .direct("What did {DL} say?", "\"That we needed to pay a fee to stay in that spot. I asked if the fee was normal and was told it was standard.\""), .direct("How much did you pay?", "\"I handed over cash for the night. Other campers told me they paid too, which made it seem official.\""), .direct("What did you do when you learned the truth?", "\"I told a real ranger. Park officials said no such ranger existed, and a letter from the agency says the same.\""), .direct("What did deputies find on {DL}?", "\"A badge bought online. It is in evidence. It did not come from any agency.\""), .cross("Did {DL} touch you or threaten you?", "\"No. It was polite. There was no threat. I handed over cash because I trusted the uniform.\""), .cross("Did {DL} say the words 'I am a ranger'?", "\"I do not recall those exact words. The uniform and badge did the talking.\""), .cross("Did you ask to see identification?", "\"No. I know I should have. I assumed the badge was enough.\""), .cross("How many campers paid?", "\"A few that I know of. I cannot give you an exact count.\""), .cross("Did {DL} hide the badge?", "\"No. It was in plain view on the chest. That is what I noticed first.\"")],
        defenseRole: "Fundraiser organizer",
        defenseExam: [.direct("What was the fundraiser?", "\"A charity event where people wear costumes. I organized it, and {D} wore a ranger-style costume at it.\""), .direct("How did {DL} act in the costume?", "\"Playful. {DF} joked with guests and greeted people in a silly voice. Everyone knew it was a costume.\""), .direct("Did {DL} collect money at the event?", "\"Only donations to the charity, which went into the donation box. Nothing for {DF} personally.\""), .direct("Did {DL} ever claim to be an officer at your event?", "\"No. Never. People laughed. It was understood to be a costume.\""), .direct("Did you know {DL} wore it at a campground?", "\"No. I never heard that until later. I would have told {DF} it was a bad idea.\""), .direct("What do you think of {DL}'s character?", "\"Kind and a bit goofy. I cannot picture {DF} meaning to cheat anybody.\""), .cross("Were you at the campground?", "\"No. I was not. I can only speak to the fundraiser.\""), .cross("A costume at a fundraiser is different from collecting fees outdoors, isn't it?", "\"Yes. It is. I would not have encouraged that.\""), .cross("Did {DL} keep any of the donations?", "\"Not that I know of. I never saw that happen.\""), .cross("Did you see the badge?", "\"Yes. It looked like a prop. It was shiny and cheap, but from a distance it looked real.\""), .cross("Would you wear a badge like that to collect money?", "\"No. A real officer would not, and I would not either. I wore it for the costume party, not to collect anything.\"")],
        theory: ("{D} posed as a ranger.", "A costume."),
        allocution: "\"That uniform was a costume I had for a fundraiser, and I tried it on and wore it to the campground that day, with a prop badge I ordered online. I never meant to fool anyone or take real fees. I'm sorry to the campers, and I'll return every dollar. I'm embarrassed.\"",
        truths: ("{DL} kept $90.", "{DL} wore the uniform at a fundraiser."),
        defendant: [.direct("Why were you wearing a ranger-style uniform?", "\"It was a costume I had for a fundraiser. I put it on to try it and I wore it to the campground that day.\""), .direct("Where did the badge come from?", "\"I ordered it online with the costume. It is a prop, not a real badge.\""), .direct("What did you do at the campsite?", "\"I walked around joking with campers about fees. I did not mean it seriously, though some people paid.\""), .direct("Did you ask anyone for money?", "\"I may have said something about a fee. I thought everyone knew it was a joke. I did not think anyone would pay.\""), .direct("What did you do with the money?", "\"I kept some of it that day. I know that was wrong. I was not thinking of it as stealing.\""), .direct("Did you ever claim to work for the park?", "\"Not in so many words. I let the costume speak. I know that was a mistake and it fooled people.\""), .cross("You took cash from campers, didn't you?", "\"I took cash from some of them. I should have handed it back or never taken it.\""), .cross("The costume looked official, didn't it?", "\"Yes. That was the point of a good costume. I did not think about how it would land at a campground.\""), .cross("No agency employs you, does it?", "\"No. I am not a ranger and I never have been.\""), .cross("You kept at it after the first camper paid, didn't you?", "\"Yes. I should have stopped. I got caught up in the joke and let it continue.\""), .cross("A badge bought online is not a prop for collecting fees, is it?", "\"No. It is not. I understand that now.\"")],
        openings: ("A person in a ranger-style uniform and a badge walked up to campers and collected camping fees in cash. Park officials say no such ranger exists, and the badge was bought online. The State will show you the badge and the campers.", "A costume is a costume. {D} wore one at a fundraiser, and a witness will tell you everyone knew it was a joke there. The question is what {D.he} intended at the campground."),
        closings: ("A uniform, a badge bought online, and cash handed over by campers who believed they were paying a ranger. No such ranger exists, and {D} kept the money.", "{D} owned up to a bad joke that grew out of a costume. The State must prove {DL} meant to impersonate an officer for gain, and a thoughtless prank is not the same."),
        timeline: [(0, "Morning: the campsite."), (0, "Morning+10: the badge."), (0, "9 a.m.: the report."), (1, "{DL} is arrested.")],
        identified: "A badge.",
        mood: .divided,
        doctrines: ["mistakeOfFact"],
        genders: ["D": .male])

    static let blueLightsRoadStopsV1 = SmallCases.make(
        key: "story.blueLightsRoadStops",
        category: .publicOrder,
        headlines: ["Driver in Tactical Vest Waves Down Cars at Lake Access Road, Demands IDs", "Reflective 'Security' Lettering Draws Complaint"],
        law: "impersonatingLEO",
        threshold: 7,
        spec: "Impersonated a law enforcement officer, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} wore a black tactical vest with 'SECURITY' printed in reflective letters and a badge-like patch at the entrance to a lake access road on {DATE}. {DL} waved down four cars, asked drivers for IDs and told two of them they could not park there. One driver called deputies. A deputy found a handheld flashlight with a red-blue strobe and the vest in {DL}'s truck. {DL} says {D.he} thought {D.his} neighborhood association had asked {D.him} to watch the road.",
        state: [E(.statement, 3, "Driver", "Was told to show an ID and move the car."), E(.physical, 3, "Vest and Patch", "Reflective vest with a badge-like patch."), E(.physical, 2, "Strobe Light", "A red-blue strobe flashlight."), E(.video, 1, "Dash Camera", "{D} waving down a car.")],
        defense: [E(.statement, 1, "Neighborhood Association", "{DL} says the association asked for help."), E(.document, 1, "Association Email", "An email about 'keeping an eye on the road'.")],
        role: "Driver",
        exam: [.direct("Where were you on {DATE}?", "\"Driving toward a lake access road, where I hoped to park and meet friends for the afternoon.\""), .direct("What happened at the entrance to the road?", "\"A person in a black tactical vest with 'SECURITY' on it in reflective letters waved me down and asked for my ID.\""), .direct("What did {DL} look like?", "\"A black vest, a badge-like patch, and a handheld light. I thought it was someone with authority over the road.\""), .direct("What did {DL} tell you?", "\"That I could not park there and that I had to move my car. I showed my ID because I did not want trouble.\""), .direct("Did you see other drivers stopped?", "\"Yes. Several. I saw a couple of other cars pulled over and one driver arguing.\""), .direct("What did you do after?", "\"I drove off and called deputies. A deputy later told me the person had no authority to stop anyone.\""), .cross("Did {DL} threaten you?", "\"No. {D} was firm, but not threatening. The way {DL} acted made me think I had to comply.\""), .cross("Did {DL} say 'I am a deputy'?", "\"No. I do not recall that. The vest and the patch suggested authority, but the word was security.\""), .cross("Did {DL} have a weapon?", "\"I did not see one. {D.He} had a flashlight with a red-blue strobe.\""), .cross("How long were you stopped?", "\"A couple of minutes. It felt longer because I was surprised.\""), .cross("Did you check whether {DL} was official?", "\"No. I did not. I showed ID because I was caught off guard.\"")],
        theory: ("{D} posed as an officer to stop drivers.", "A volunteer who overstepped."),
        allocution: "\"My neighborhood association talked about keeping an eye on the access road, and I thought that included wearing a vest and waving down cars. I overstepped. I'm sorry to the drivers I stopped, and I'll never do it again. I was angry and I made it everyone else's problem.\"",
        truths: ("{DL} asked drivers whether they had 'warrants'.", "The association never authorized stopping cars."),
        defendant: [.direct("Why were you standing at the road entrance?", "\"My neighborhood association had mentioned keeping an eye on the access road. I thought they wanted me to watch it.\""), .direct("What were you wearing?", "\"A black vest that says security, and a patch. I wore it so people would see me and know I was helping.\""), .direct("What did you ask drivers?", "\"I waved down a few and asked for IDs. I told two of them they could not park there.\""), .direct("Did you think you were allowed to do that?", "\"Yes. An email from the association said to keep an eye on the road. I took it further than I should have.\""), .direct("Why did you have a strobe light?", "\"It is a flashlight I own. I used it to wave cars down at dusk. I did not think of it as a police tool.\""), .direct("What did you do when a deputy arrived?", "\"I explained what I thought I was doing. I told the truth about the email and the vest.\""), .cross("The email said 'keeping an eye on the road,' not stopping cars, didn't it?", "\"Yes. That is what it said. I stretched it.\""), .cross("You asked drivers for IDs, didn't you?", "\"I did. I should not have. I was playing a role I had no right to.\""), .cross("The vest said SECURITY, correct?", "\"Yes. And the patch looked like a badge. I wanted to look official, and that was wrong.\""), .cross("You told two drivers they could not park, didn't you?", "\"Yes. I thought that was the association's rule. I did not check.\""), .cross("No one authorized you to stop cars, did they?", "\"No. No one did. That was my mistake.\"")],
        openings: ("A person in a tactical vest marked SECURITY and a badge-like patch waved down four cars at a lake access road, asked for IDs, and told two drivers they could not park. A deputy found the vest and a strobe light in {D}'s truck. The State will show it.", "A neighborhood association email said to keep an eye on the road. {D} took that to heart, too far, but never claimed to be a deputy and never touched anyone."),
        closings: ("A vest that said SECURITY, a badge-like patch, a strobe light, and four cars stopped. No one gave {D} that authority, and drivers handed over IDs because they believed it.", "{D} believed the association wanted help watching the road and never claimed to be an officer. The State has not proved {DL} meant to impersonate one."),
        timeline: [(-3, "The association emails about the road."), (0, "10 a.m.: {D} waves down cars."), (0, "10:40 a.m.: a driver calls deputies."), (0, "11:15 a.m.: a deputy arrives."), (0, "11:30 a.m.: the vest is seized.")],
        identified: "A driver's report.",
        mood: .divided,
        doctrines: ["mistakeOfFact"],
        genders: ["D": .male])

    static let windowFilmingNeighborV1 = SmallCases.make(
        key: "story.windowFilmingNeighbor",
        category: .violent,
        headlines: ["Neighbor Mounted Cameras on a Pole Facing a Backyard", "Followed Her on Her Run"],
        law: "stalking",
        threshold: 7,
        spec: "Willfully harassed {V} on more than one occasion without legitimate purpose, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "For two months {V} saw {D}, a neighbor, filming {V.his} backyard and following {V.him} on runs. A pole camera faced {V}'s patio. {DL} says it was for bird watching.",
        state: [E(.physical, 3, "Pole Camera", "Faces {V}'s patio.", .search), E(.video, 3, "Footage", "Hours of {V} outdoors."), E(.statement, 2, "Running Partner", "{D} followed on a bike.")],
        defense: [E(.statement, 1, "Birds", "{DL} says it was for bird watching.")],
        role: "Running partner",
        exam: [.direct("What did you see as {V}'s running partner?", "\"{D}, a neighbor, followed us on runs, riding a bike behind us. It happened over two months.\""), .direct("What was found at {D}'s home?", "\"A pole camera aimed at {V}'s patio. The footage shows hours of {V} outdoors.\""), .direct("What did {V} tell you?", "\"That {DL} had been filming {V.his} backyard and following {V.him} on runs. {V} was frightened.\""), .direct("Tell the jury about your running with {V}.", "\"I run with {V} three mornings a week along neighborhood paths. We have been training together for a long time, and we know the route well.\""), .direct("What did you notice about the defendant?", "\"For about two months, a neighbor followed us on a bike along the same paths. {D.He} kept a distance but stayed behind us for miles.\""), .direct("What did {V} tell you about the camera?", "\"{V} said a pole camera was aimed at {V}'s patio and that {V} felt watched in the backyard. {V} was upset, and I could see it.\""), .cross("{D} says it was for bird watching, doesn't {D.he}?", "\"A bird feeder hung near the pole. I will agree that is true.\""), .cross("Did the defendant ever say anything threatening?", "\"No. {D.He} never spoke to us. {D.He} just followed on a bike.\""), .cross("Was the defendant warned to stop?", "\"Yes. {D.He} had been warned in writing.\""), .cross("Did {D} ever speak to you or threaten {V}?", "\"No. {DL} never said a word to us. I never heard a threat, but the following made us uneasy for weeks.\""), .cross("Could the defendant have been riding on those paths for exercise?", "\"Possibly. Many people use those paths. But {D.he} rode behind us every single morning, and that seemed like more than a coincidence.\"")],
        defenseRole: "Birding friend",
        defenseExam: [.direct("Does {D} watch birds as a hobby?", "\"Yes. {D} watches birds every morning, and I go out with {DF} sometimes with binoculars.\""), .direct("Does the defendant watch birds from the pole camera area?", "\"The camera is near a feeder. I do not know exactly what it covers.\""), .direct("Does the defendant's camera cover {V}'s patio?", "\"I do not know. I have not seen the footage. I only know about the birds.\""), .direct("Please describe your friendship with the defendant.", "\"We have birded together for years. We meet before dawn at a few spots, and I have seen how patient and quiet {DF} is with the hobby.\""), .direct("What do you know about the defendant's pole camera?", "\"{D.He} showed me. It sits near a feeder, and the point is to catch birds as they land. I have seen the birds it recorded.\""), .direct("Have you ever seen the defendant act in a threatening way toward anyone?", "\"Never. {DF} is quiet and keeps to {D.himself}. In all the years I have known {DF}, I have not seen {DF} act aggressively toward a neighbor.\""), .cross("Did the defendant mention {V} to you?", "\"Once. {DF} said {V} had complained. That is all.\""), .cross("Have you seen a bird feeder at the pole?", "\"Yes. A feeder hung there. It is real.\""), .cross("Did you ever see the defendant on a bike following runners?", "\"No. I never saw that. I only know {D.him} from birding, and I cannot say what {D.he} did on other mornings.\""), .cross("Have you seen the footage of {V}'s patio?", "\"No. I have not seen it. I cannot say whether the camera faced the patio or how often it recorded {V}.\""), .cross("You have never seen the footage from the pole camera, have you?", "\"No. I know {D.he} loves birds and builds feeders. I have never seen what the camera recorded.\"")],
        theory: ("{D} stalked a neighbor.", "Bird watching."),
        allocution: "\"I crossed a line, and I'm sorry. That camera on my pole covers my own yard and a bird feeder, and I never meant to aim it at {V}'s patio. I love watching birds. I understand how it looked, and I'll take it down and respect {V.his} privacy.\"",
        truths: ("{DL} had been warned in writing.", "A bird feeder hung near the pole."),
        defendant: [.direct("Did you film {V}'s backyard?", "\"The camera covers my own yard and a feeder. It may catch part of {V}'s patio. I did not aim it at {V.him}.\""), .direct("Why did you put a camera on a pole?", "\"I watch birds, and a pole by a feeder gives me a good view.\""), .direct("Why did you follow {V} on a bike?", "\"I ride the same paths. I was not following {V.him}. I happened to be going the same way.\""), .direct("Please describe your hobby.", "\"I have watched birds for years. I keep a feeder in my yard and record what visits. A camera on a pole helps me see which birds come.\""), .direct("Where is your pole camera aimed?", "\"At my own yard and the feeder. I did not mean for it to face {V}'s patio, and I did not realize the angle caught the neighbor's yard.\""), .direct("Why were you on the same paths as {V}?", "\"I ride the same paths for exercise. I ride at that time of the morning, and I did not know {V} had noticed me or was bothered.\""), .cross("The camera faces {V}'s patio, doesn't it?", "\"It seems to. I did not set it that way on purpose.\""), .cross("Hours of footage show {V} outdoors. Is that birds?", "\"It is footage of my yard that includes {V}. I did not watch it for that.\""), .cross("You were warned in writing to stop, weren't you?", "\"Yes. I received a written warning. I did not agree with it, but I should have moved the camera right away.\""), .cross("The footage shows hours of {V} outdoors, doesn't it?", "\"It does. I did not review it carefully. The camera recorded whatever was in the frame, and {V} was in the frame.\""), .cross("The camera records all day, not only when birds are at the feeder, doesn't it?", "\"It records continuously, because I never know when birds will come. That is how the footage ended up with hours of {V.him} in it.\"")],
        openings: ("For two months, {V} saw {D}, a neighbor, filming {V}'s backyard and following {V} on runs. A pole camera faced {V}'s patio, and {DL} had been warned in writing.", "The defense evidence will establish that {D} watches birds, that a feeder hangs near the pole, and that {DL} never meant to film {V} or follow anyone."),
        closings: ("A pole camera aimed at {V}'s patio, hours of footage, a neighbor on a bike behind every run, and a written warning that was ignored. {V} lived in fear.", "A bird watcher with a feeder and a camera on a pole. The State must prove {D} aimed that camera at {V} to harass."),
        timeline: [(-60, "The pole goes up."), (0, "Month 2: the bike."), (0, "Month 2: the footage is found."), (1, "{DL} is arrested.")],
        identified: "A pole camera.",
        mood: .wantsConviction,
        impact: "I stopped going outside, even to water my plants. For two months a camera on a pole looked at my patio, and I'd see a man following me on my runs. I gave up my morning jogs and started driving to the gym. I just wanted my own yard to feel mine.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let firedWorkerTextsV1 = SmallCases.make(
        key: "story.firedWorkerTexts",
        category: .violent,
        headlines: ["Laid-Off Welder Sends Threatening Emails to Plant Supervisor", "Messages Mention the Supervisor's Dog"],
        law: "communicatingThreats",
        threshold: 7,
        spec: "Communicated a threat to {V} to cause fear, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After a layoff, {D} sent {V}, a plant supervisor, 14 emails on {DATE} saying {V.he} would 'pay' and mentioning {V.his} dog. {DL} says it was venting.",
        state: [E(.digital, 3, "Emails", "Fourteen threatening emails."), E(.document, 2, "Layoff Notice", "The week before."), E(.statement, 2, "Spouse", "The family left for a weekend.")],
        defense: [E(.statement, 1, "Venting", "{DL} says it was venting.")],
        role: "Plant supervisor",
        exam: [.direct("What is your job at the plant?", "\"I am a plant supervisor. I run a shift, handle schedules, and had a hand in the layoff list the week before.\""), .direct("What did you receive on {DATE}?", "\"Fourteen emails from {D}, who had been laid off. They said I would 'pay' and mentioned my dog.\""), .direct("Why did the dog mention bother you?", "\"It meant {DL} knew about my home and my pet. It felt like a way to say 'I know where you live.'\""), .direct("How did you react?", "\"I felt unsafe. My family left for a weekend away, and I called deputies to report the emails.\""), .direct("What had happened between you and {DL}?", "\"{D.He} was on the layoff list the week before. There had been a tense conversation when the notice was handed out.\""), .direct("What does your spouse say?", "\"My spouse says our family left the house for the weekend because we were afraid. The statement is in evidence.\""), .cross("Did {DL} ever come to your house?", "\"I do not know of any visit. The emails were the threat. Nothing was left at the door that I saw.\""), .cross("Had {DL} ever been violent at work?", "\"No. Never. {DL} was a decent worker with no violent history.\""), .cross("Did you reply to the emails?", "\"No. I did not engage. I forwarded them and called the deputies.\""), .cross("Did {DL} say anything about weapons?", "\"Not that I recall. The tone was angry and the word 'pay' stood out.\""), .cross("Was the layoff based on seniority or performance?", "\"Both factors. It was a company decision, and I was one voice among several.\"")],
        defenseRole: "Coworker",
        defenseExam: [.direct("How do you know {DL}?", "\"I worked beside {D} for years on the line. I considered {DF} a friend and a solid coworker.\""), .direct("How did {DL} take the layoff?", "\"Hard. {D.He} was angry and hurt, and said some harsh things to me that week.\""), .direct("Was {DL} the kind of person to carry out a threat?", "\"No. I have never seen {DF} raise a hand to anyone. {DF} is loud when upset but not violent.\""), .direct("Did {DL} ever talk about hurting the supervisor?", "\"No. Only that it was unfair. Never anything about harm.\""), .direct("Did you see the emails?", "\"I heard about them. I did not see them. I would be surprised if {DF} meant them.\""), .direct("What would you say about {DL}'s state of mind that week?", "\"Overwhelmed. {D.He} had bills and was scared. People say things when they are scared.\""), .cross("You are {DL}'s friend, aren't you?", "\"Yes. That is why I am telling you what I know of {D.his} character.\""), .cross("Did you tell {DL} not to write angry emails?", "\"No. I did not know. If I had, I would have said so.\""), .cross("Did {DL} ever talk to you about the supervisor's home?", "\"No. Never. {DL} never talked to me about the supervisor's home.\""), .cross("Do people ever follow through on threats?", "\"Sometimes. I cannot promise. I only know {D.him}.\""), .cross("You do not know what {D} meant by the emails, do you?", "\"I do not. I know {DF} was devastated after the layoff, but I cannot read the mind of someone writing in anger.\"")],
        theory: ("{D} threatened a supervisor.", "Venting."),
        allocution: "\"I was angry and hurt about the layoff, and I typed things I didn't mean. I meant the plant would regret letting me go. I never meant harm to a person, and I regret mentioning {V.his} dog.\"",
        truths: ("{DL} drove past the house once.", "{DL} apologized by email."),
        defendant: [.direct("Why did you send those emails?", "\"I was angry and hurt about the layoff. I typed things I did not mean. I was venting.\""), .direct("What did you mean by 'pay'?", "\"I meant the plant would regret letting me go. I did not mean any harm to a person.\""), .direct("Why did you mention the dog?", "\"I knew the supervisor had a dog. I was trying to sound sharp. It was cruel and I regret that.\""), .direct("Did you drive past the house or watch it?", "\"No. I did not go near the house. I stayed home and typed from my couch.\""), .direct("How did you feel after sending them?", "\"Ashamed. I realized how it would read. I tried to calm down and I wished I could take them back.\""), .direct("Did you ever plan to hurt anyone?", "\"No. I have never hurt anyone. I was shaken by losing my job and I lashed out with words.\""), .cross("Fourteen emails is more than a single outburst, isn't it?", "\"Yes. I kept going. That was a failure to stop myself.\""), .cross("You mentioned a family pet, didn't you?", "\"Yes. It was a low blow. I am sorry for it.\""), .cross("You knew {V} was a supervisor involved in the layoff, didn't you?", "\"I knew {V} had a role. I blamed {V} in my anger.\""), .cross("The family left for the weekend because of your emails, didn't they?", "\"I did not know that. I understand now why. I am sorry for frightening anyone.\""), .cross("You used the word 'pay,' didn't you?", "\"I did. It is a word I should not have used.\"")],
        openings: ("After a layoff, {D} sent {V}, a plant supervisor, 14 emails saying {V} would 'pay' and mentioning {V}'s dog. {V}'s family left the house for the weekend, and the State will show you the emails and why they were frightening.", "A bad week and a keyboard. {D} lost a job, vented in angry emails, and never went near the house. Listen for a friend who has never seen {DL} lay a hand on anyone."),
        closings: ("Fourteen emails, a promise that {V} would 'pay,' and a reference to {V}'s dog. A family left home in fear. Words aimed at a person's safety are a crime.", "{D} was venting after losing a job and never went near the house or touched anyone. The State has not proved a true threat, only an angry person with a keyboard."),
        timeline: [(-1, "The layoff."), (0, "8 p.m.: the emails."), (0, "9 p.m.: {V} calls deputies."), (1, "{DL} is arrested.")],
        identified: "Emails.",
        aggravating: ["The offense involved a threat"],
        mood: .divided,
        impact: "We changed our routine after those emails. I stopped walking my dog at night, and I varied my route to the plant. Fourteen messages came in one day, and one mentioned my dog by name. I'd worked with that man for years and never thought {D.he} could scare me.",
        doctrines: ["relevance"])

    static let hospitalBombCallV1 = SmallCases.make(
