        state: [E(.digital, 3, "Call Record", "A prepaid phone."), E(.video, 3, "Store Camera", "{D} buys the phone."), E(.statement, 2, "Dispatcher", "A male voice.")],
        defense: [E(.statement, 1, "Stolen", "{DL} says the phone was stolen.")],
        role: "911 dispatcher",
        exam: [.direct("What call did you take on {DATE}?", "\"A caller told 911 a gunman was inside a clinic. I kept the line open as long as I could and sent it to responders.\""), .direct("What happened at the clinic?", "\"A two-hour lockdown. Staff and patients sheltered in place while deputies cleared the building.\""), .direct("How did you describe the voice?", "\"A male voice, steady, with no obvious emotion. It sounded rehearsed. It did not sound panicked.\""), .direct("What did the call record show?", "\"The call came from a prepaid phone. We pulled the record right away and began tracing the number.\""), .direct("How was the phone tied to {DL}?", "\"A store camera shows {D} buying that phone. The sale record and the video line up.\""), .direct("Was a gunman ever found?", "\"No. The building was searched and nothing was found. The call was false.\""), .direct("How long did the lockdown last, and who was affected?", "\"About two hours. Staff, patients, and visitors sheltered in place while deputies searched every room, and several appointments were cancelled until the clinic was cleared.\""), .cross("Can you say whose voice it was?", "\"No. I cannot identify the voice. I only describe what I heard on the recording.\""), .cross("Did the caller give a name?", "\"No. The call was anonymous. No name, no explanation.\""), .cross("Was anyone hurt in the lockdown?", "\"No. People were frightened, but no one was injured.\""), .cross("Did you see {DL} on the camera making the call?", "\"No. The camera shows a purchase, not a call. I cannot place the phone in anyone's hand at the time.\""), .cross("Could the phone have changed hands after the sale?", "\"Yes. That is possible. Prepaid phones are bought and given away every day.\"")],
        defenseRole: "Phone store clerk",
        defenseExam: [.direct("What do you do at the phone store?", "\"I work the counter, selling phones and prepaid plans. I ring up customers all day.\""), .direct("Do you remember selling a phone to {DL}?", "\"Yes. {D} bought a prepaid phone. We have the sale record.\""), .direct("How did the sale go?", "\"Ordinary. {D.He} paid, took the phone, and left. Nothing unusual.\""), .direct("When was the sale?", "\"Weeks before the call. I have the date in the record.\""), .direct("Did {DL} say what the phone was for?", "\"A spare, I think. People buy spares for travel and for kids.\""), .direct("Do prepaid phones get lost or stolen?", "\"All the time. Customers come back to tell us. It is common.\""), .direct("Do you recall whether {D} said anything about the phone at the register?", "\"Only that {DF} wanted something cheap and prepaid. {DF} did not mention a reason for it, and the store does not ask why a customer wants a phone.\""), .direct("Does your store keep a record of sales like this one?", "\"Yes. Every sale is on camera and recorded in the register. The camera shows {DF} buying the phone, and the receipt matches the date and the phone's number.\""), .cross("Can you say who used the phone after the sale?", "\"No. I only know who bought it.\""), .cross("Did {DL} come back to report it stolen?", "\"I do not recall that. I do not handle reports.\""), .cross("Do you remember every customer?", "\"No. I remember {D.he} because I checked the record afterward.\""), .cross("Did {DL} seem upset about anything?", "\"Not at the counter. {D.He} seemed calm.\""), .cross("Would you know if the phone was used for a hoax?", "\"No. I have no way to know.\"")],
        theory: ("{D} called in a gunman.", "A stolen phone."),
        allocution: "\"I'm so sorry for what the staff and patients went through during that lockdown. I was a patient at that clinic once, and I wouldn't threaten the people who treated me. I bought that phone as a cheap backup, and it went missing before the call was made.\"",
        truths: ("{DL} had a dispute with the clinic.", "{DL} reported the phone stolen a day later."),
        defendant: [.direct("Did you place that call?", "\"No. I did not. I was a patient at that clinic once, and I would not threaten the people who treated me.\""), .direct("Do you own a prepaid phone?", "\"I bought one, yes. I bought it as a cheap backup. It went missing before the call was made.\""), .direct("When did it go missing?", "\"I noticed it was gone some days after I bought it. I did not file a report. I should have, yes.\""), .direct("What was your relationship with the clinic?", "\"I had a billing dispute and I was frustrated. But I have never wished anyone harm there.\""), .direct("Where were you when the call came in?", "\"At home. I found out about the lockdown later on the news. I was shocked.\""), .direct("Did you try to find the phone?", "\"I looked around. I thought I had lost it. I did not think it would turn up in a crime.\""), .direct("What did you do the day the lockdown happened?", "\"I stayed home and watched the news in disbelief. I never called anyone about a gunman, and I told the deputies who came to my door that the call was not mine.\""), .cross("The store camera shows you buying that phone, doesn't it?", "\"Yes. I did buy it. I never said otherwise.\""), .cross("You had a dispute with the clinic, didn't you?", "\"Yes. About a bill. It was a real dispute, and I was upset.\""), .cross("You did not report the phone missing at once, did you?", "\"No. A day later I did. I should have been faster.\""), .cross("Someone knew you had a grudge, correct?", "\"Perhaps. That is why they might have used my phone. It does not mean I made the call.\""), .cross("You cannot prove the phone was stolen, can you?", "\"No. I cannot. I only know I did not have it.\"")],
        openings: ("A caller told 911 that a gunman was inside a clinic, and a two-hour lockdown followed. The prepaid phone used for the call was bought on camera by {D}, a former patient. The State will show the call record and the sale.", "{D} bought a phone, and the phone later vanished. A store clerk will confirm when it was sold and the timing leaves room for someone else to have used it."),
        closings: ("A false report of a gunman, a two-hour lockdown, and a prepaid phone that {D} bought on camera. The phone leads to {D.him}.", "A phone is not a voice. It was bought weeks before the call and no one has identified who spoke. The State has not proved {D} made the call."),
