        doctrines: ["burdenOfProof"])

    static let trailerToddlerNeglectV1 = SmallCases.make(
        key: "story.trailerToddlerNeglect",
        category: .family,
        headlines: ["Toddler Locked in Apartment Bedroom for Two Days While Caregiver Was Away on a Trip", "Landlord Hears Crying, Opens Door With Key"],
