        state: [E(.statement, 3, "Landlord", "Heard crying for two days."), E(.document, 3, "Medical Report", "Dehydration requiring two nights in the hospital."), E(.physical, 2, "Bedroom", "Locked door and an empty bottle.")],
        defense: [E(.statement, 1, "Aunt", "{DL} says an aunt was to check in."), E(.digital, 1, "Texts", "A text asking the aunt to stop by.")],
        role: "Landlord",
        exam: [.direct("What did you find inside?", "\"{V}, two years old, in a locked bedroom, dehydrated and in a soiled diaper, with a nearly empty bottle.\""), .direct("What happened to {V}?", "\"{V} was hospitalized for two nights for dehydration. The medical report records it.\""), .direct("Tell us about your building.", "\"I own a small apartment building and live nearby. I know most tenants, and I walk the halls often to check on repairs.\""), .direct("What did you hear through the wall?", "\"A child crying for two days. At first I thought it was a passing fuss, but on the second day the crying sounded weak, and I got worried.\""), .direct("How did you get into the apartment?", "\"I knocked and no one answered, so I used my key. A bedroom door was locked from the outside, and I opened it.\""), .direct("What did you do right after you opened the bedroom door?", "\"I called 911 and carried {V} to the kitchen for water. I stayed with {V} until the paramedics came in.\""), .cross("{D} says an aunt was supposed to check on {V}, doesn't {D.he}?", "\"That is what {D} says. I did not see an aunt come.\""), .cross("Where was the defendant?", "\"Away on a trip. {D.He} had left days earlier.\""), .cross("Did you call anyone before opening the door?", "\"No. I opened it because the crying did not stop.\""), .cross("Did you see the defendant leave for the trip?", "\"I saw {DL} leave with a bag. I did not know how long {DL} would be gone, and I did not know {V} had been left alone.\""), .cross("Did you speak to any relative of the defendant?", "\"An aunt came by after I called the sheriff. The aunt said the request was to check in, and no one had said how long {DL} would be away.\"")],
        theory: ("{D} left a toddler locked in a room for days.", "A caregiver who relied on a relative."),
        allocution: "\"I thought an aunt was going to check on {V} while I was away, and I'd arranged it before I left. I should have called her on the second day. I love {V.him}, and I'm sorry for what {V.he} went through. I should have gotten help before it came to this.\"",
        truths: ("{DL} had not called the aunt until the second day of the trip.", "{DL} posted trip photos while {V} was alone."),
        defendant: [.direct("Why did you leave {V} alone?", "\"I thought an aunt was going to check on {V.him}. I arranged it before I left.\""), .direct("When did you call the aunt?", "\"On the second day of the trip. I should have called sooner.\""), .direct("What can you tell us about your family and the trip?", "\"I take care of {V} by myself. I went on a short trip to see friends, and I thought a relative would be there to look after {V}.\""), .direct("What did you do to arrange for care?", "\"I asked a relative, an aunt, to stop by and check on {V}. I sent a text, and I thought that was enough, but I never confirmed that the aunt agreed.\""), .direct("Why was the bedroom locked?", "\"I locked it so {V.he} would be safe in the room. I did not want {V.him} wandering around the apartment, and I thought a few hours would be fine.\""), .direct("What did you tell the aunt before you left?", "\"That I would be gone a few days and asked the aunt to stop by. I texted but did not hear back, and I did not call again until the second day.\""), .cross("You posted trip photos while {V} was alone, didn't you?", "\"I did not know {V} was alone. I am ashamed.\""), .cross("A two-year-old was locked in a bedroom for two days. Isn't that neglect?", "\"It is. I trusted the wrong plan.\""), .cross("You did not call the aunt until the second day of the trip, did you?", "\"That is true. I should have called the aunt much sooner. I assumed it was handled, and I regret not following up immediately.\""), .cross("{V} was a toddler alone for two days, wasn't {V.he}?", "\"Yes. I know how serious that is. I did not realize it would last that long, and I am ashamed of what happened.\""), .cross("{V} could not open that bedroom door from the inside, could {V.he}?", "\"No, {V.he} could not. I locked it from the outside, and I should have thought about that before I left.\"")],
        openings: ("A landlord heard a child crying for two days and opened the door with a key. {V}, age two, was in a locked bedroom, dehydrated, with a nearly empty bottle, and {V} was hospitalized for two nights. {D}, the caregiver, had left for a trip.", "The defense witnesses will explain that {D} arranged for an aunt to check on {V} before leaving, and that {DL} believed the plan was safe and the child would be looked after."),
        closings: ("A locked bedroom, two days of crying, a two-year-old dehydrated and hospitalized, and a caregiver posting trip photos. {D} left {V} alone.", "A caregiver who arranged for an aunt to check in and who was let down. The State must prove culpable neglect and not a failed plan."),
        timeline: [(-3, "{D} leaves for the trip."), (-1, "The crying starts."), (0, "The landlord opens the door."), (0, "{V} is taken to the hospital."), (1, "{D} is located.")],
        identified: "A landlord's account.",
        mood: .wantsConviction,
        doctrines: ["lesserIncluded"],
        genders: ["D": .female, "V": .male])

    static let babysitterInfantInjuryV1 = SmallCases.make(
