        exam: [.direct("What did the texts between {D} and {V} show?", "\"{D} and {V} planning a drive to a concert two states away. {V} was sixteen when {V} left home.\""), .direct("What did {V}'s parent say?", "\"The parent never consented and reported {V} missing the next morning.\""), .direct("What other evidence tied the defendant to the trip?", "\"A toll camera and gas receipts across the state line. {V}'s sixteenth birthday post was also public.\""), .direct("How would you describe your job as a detective?", "\"I investigate crimes involving minors for the sheriff's office. I interview families, review phone and travel records, and work with other states on cases that cross state lines.\""), .direct("What time did the parent call?", "\"A little before seven. The call is in our dispatch log.\""), .direct("How did you track the car?", "\"A toll camera and gas receipts placed the car across the state line. We found {V} at the concert, safe, and {DL} had driven the whole way.\""), .cross("{D} says {V} wrote that {V.he} was eighteen, doesn't {D.he}?", "\"Yes. A message from {V} says eighteen. That is fair.\""), .cross("When did the defendant see {V}'s birthday post?", "\"Two weeks before. I understand {DL} saw it.\""), .cross("Did the defendant ask {V} to delete messages?", "\"Yes. {DL} asked {V} to delete the messages.\""), .cross("Did {V} agree to go on the trip?", "\"Yes. The texts show {V} helped plan it. {V} was sixteen, though, and a parent had not agreed to any of it.\""), .cross("Did {V} write that {V.he} was eighteen?", "\"A dating profile listed an age of eighteen, and a message said the same. But a birthday post two weeks earlier showed {V} turning sixteen.\"")],
        theory: ("{D} drove a sixteen-year-old out of state without a parent's consent.", "A driver who believed {V} was an adult."),
        allocution: "\"{V} told me in a message that {V.he} was eighteen, and I took {V.him} at {V.his} word and didn't check. I picked {V.him} up at the bus station and drove to the concert. I'm sorry to {V.his} family for the days of worry. I should have gotten help before it came to this.\"",
        truths: ("{DL} saw {V}'s sixteenth birthday post two weeks before.", "{DL} asked {V} to delete the messages."),
        defendant: [.direct("Did you drive {V} across the state line?", "\"Yes. I picked {V} up at the bus station and drove to the concert. {V} told me {V.he} was eighteen.\""), .direct("Why did you believe {V} was eighteen?", "\"{V} wrote it in a message. I took {V.him} at {V.his} word. I did not check.\""), .direct("Did you see the birthday post?", "\"I saw it two weeks before, I think. I did not connect it. I should have, yes.\""), .direct("Walk us through how you met {V}.", "\"We met online and chatted for a few months. We shared a love of the same band, and {V} was excited about the concert.\""), .direct("What did {V} tell you about {V.his} age?", "\"{V} wrote in a message that {V.he} was eighteen, and a dating profile said the same. I took {V.him} at {V.his} word, and I did not ask for proof.\""), .direct("Why did you pick {V} up at the bus station?", "\"{V} had no ride, and I had a car. We planned the trip together, and I drove us across the state line to the concert.\""), .cross("{V}'s sixteenth birthday post was public. Didn't that tell you?", "\"It did. I made a mistake.\""), .cross("You drove a sixteen-year-old across a state line without the parent's consent, didn't you?", "\"Yes. I did. I regret it.\""), .cross("You saw the sixteenth birthday post two weeks before, didn't you?", "\"I saw it, but I thought it was an old post. I did not think carefully about it, and I know how that sounds.\""), .cross("You asked {V} to delete the messages, didn't you?", "\"Yes. I was worried about trouble. That was a poor choice, and I should have called a parent immediately instead.\""), .cross("You picked {V} up at a bus station rather than at {V.his} home, didn't you?", "\"Yes, at the bus station, because {V} said there was no ride. I never met a parent and never went to the house.\"")],
        openings: ("{V}, sixteen, left home after texting {D} a plan to drive to a concert two states away. {DL} picked {V} up at a bus station and drove across the state line, and the parent reported {V} missing the next morning.", "Weigh the defense proof, which will show that {V} wrote in a message that {V.he} was eighteen and that {D} honestly believed it and meant only to give {V} a ride."),
        closings: ("Texts that planned the trip, a sixteenth birthday post two weeks earlier, and a request to delete the messages. {D} knew {V}'s age and drove across the line anyway.", "{V} wrote that {V.he} was eighteen, and {D} took it at face value. The State must prove {DL} knew {V} was a minor."),
        timeline: [(-3, "{D} and {V} plan the trip."), (0, "{V} leaves home."), (0, "{D} crosses the state line."), (1, "A parent reports {V} missing."), (2, "{V} is found at the concert.")],
        identified: "A toll camera.",
        mood: .wantsConviction,
        doctrines: ["mistakeOfFact"],
        genders: ["D": .male, "V": .female])

    static let benefitCardCashV1 = SmallCases.make(
        key: "story.benefitCardCash",
        category: .whiteCollar,
        headlines: ["Corner Market Billed Infant Formula Program for $28,000 in Sales Inventory Can't Support", "Distributor Invoices Show Far Less Formula Bought"],
        law: "falsePretenses",
        threshold: 7,
        spec: "Obtained property by false pretenses from {V}, a nutrition benefits program, valued at $28,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A corner market, owned by {D}, billed a nutrition program for $28,000 in infant formula over nine months. An investigator compared the billing with the market's distributor invoices and found the market bought less than a third of that formula. The terminal records showed many transactions at 3 a.m. {D.He} says distributors short-shipped and that some formula came from a cousin's warehouse.",
        state: [E(.document, 3, "Program Audit", "$28,000 billed against about $9,000 bought."), E(.document, 3, "Distributor Invoices", "Formula purchases far below the billing."), E(.digital, 2, "Terminal Records", "Dozens of transactions between 2 and 4 a.m."), E(.statement, 1, "Delivery Driver", "Never delivered formula in those volumes.")],
        defense: [E(.statement, 1, "Cousin's Warehouse", "{DL} says a cousin supplied formula without invoices."), E(.document, 1, "Cash Purchases", "Some cash receipts for formula.")],
        role: "Program investigator",
        exam: [.direct("What did your audit find about the market's billing?", "\"The market billed a nutrition program for $28,000 in infant formula over nine months, but distributor invoices show purchases of roughly $9,000.\""), .direct("How did you compare the numbers?", "\"I matched every billed transaction against the market's distributor invoices and delivery receipts. The formula bought did not come close to the formula billed.\""), .direct("What did the terminal records show?", "\"Dozens of transactions between 2 and 4 a.m., round amounts, with no customer who remembers buying formula then.\""), .direct("Did a delivery driver add anything?", "\"The driver told us formula was never delivered in those volumes to this market.\""), .direct("Who owns the market?", "\"{D}, the owner. The terminal credentials and the billing were under {D.his} account.\""), .direct("What explanation did {DL} offer?", "\"That distributors short-shipped and that some formula came from a cousin's warehouse, without invoices.\""), .cross("Do cash purchases for formula sometimes happen?", "\"Yes. A few receipts exist. But they do not cover $28,000.\""), .cross("Can short shipments cause an invoice gap?", "\"They can cause small gaps. A gap this large would be unusual.\""), .cross("Did you speak with the cousin?", "\"I tried. The cousin said no formula was supplied. I can only report that.\""), .cross("Were the 3 a.m. transactions all fraudulent?", "\"I cannot say each one. But they cluster in a way that does not match any shift.\""), .cross("Did {DL} cooperate with the audit?", "\"Yes. {D.He} produced records and answered questions. I will give credit for that.\"")],
        theory: ("{D} billed a nutrition program for formula never sold.", "A grocer who bought formula off the books."),
        allocution: "\"My market serves a neighborhood where many families use that nutrition program, and some of my customers shop at odd hours. I entered some sales late when I got behind, so the timestamps are off. I'm sorry for the confusion, and I'll cooperate fully.\"",
        truths: ("{DL}'s market has no recorded customer who bought formula at 3 a.m.", "The cousin says {D.he} never supplied formula."),
        defendant: [.direct("What do you sell at your market?", "\"Groceries and infant formula, mostly. I serve a neighborhood where many families use the nutrition program.\""), .direct("Why are there transactions at 3 a.m.?", "\"Some customers shop at odd hours. I also entered sales late when I got behind. The timestamps are off.\""), .direct("Where did the formula come from?", "\"Distributors, and some from a cousin's warehouse. I paid cash for some of it without invoices.\""), .direct("Did you bill for formula you did not sell?", "\"No. I billed what I sold. My records were messy, and I know that makes it look worse.\""), .direct("Why do invoices show so little formula?", "\"Short shipments, and the cash purchases are not in the invoices. I should have kept receipts.\""), .direct("How did you feel about the audit?", "\"Scared. I knew my books were poor. I never meant to cheat the program.\""), .cross("The invoices show about $9,000 against $28,000 billed, don't they?", "\"Yes. The numbers do not match. I have no good explanation for all of it.\""), .cross("You cannot produce records for the cousin's supply, can you?", "\"No. It was cash and talk. I know that is not proof.\""), .cross("The transactions at 3 a.m. had no customer behind them, did they?", "\"I cannot name one. I cannot explain them.\""), .cross("The program paid your market for formula it never bought, didn't it?", "\"That is how it looks. I did not do it on purpose.\""), .cross("You keep the terminal, don't you?", "\"Yes. The terminal is under my login. I take responsibility.\"")],
        openings: ("A corner market billed a nutrition program for $28,000 in infant formula over nine months, but its distributors delivered about $9,000 worth. Dozens of transactions came at 3 a.m. The State will show the audit and the terminal records.", "Messy books are not the same as fraud. {D} says sales were real, some formula came without invoices, and the paperwork is poor but not a plan to steal."),
        closings: ("Twenty-eight thousand dollars billed, about nine thousand bought, and swipes at 3 a.m. with no customers behind them. The program paid for formula that never existed.", "Poor records and cash purchases do not prove a scheme. The State has not shown {D} billed for formula {DL} knew was never sold."),
        timeline: [(-270, "Billing starts."), (-90, "The program flags the account."), (0, "The investigator compares the invoices."), (10, "The terminal records are pulled."), (20, "{D} is interviewed.")],
        identified: "A program audit.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let therapyBillingGhostV1 = SmallCases.make(
        key: "story.therapyBillingGhost",
        category: .whiteCollar,
        headlines: ["Medical Equipment Supplier Billed Insurers $140,000 for Power Wheelchairs Never Delivered", "Patients Say They Never Got a Chair"],
        law: "insuranceFraud",
        threshold: 8,
        spec: "Presented false claims to an insurer, {V}, totaling $140,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A medical equipment supplier owned by {D} billed insurers $140,000 for twenty-two power wheelchairs. An investigator contacted the patients, and most said they never received a chair. Delivery receipts bore signatures that did not match. The warehouse held three chairs. {DL} says employees handled the paperwork and some deliveries were made by a contractor.",
        state: [E(.document, 3, "Claims", "Twenty-two chairs billed to insurers."), E(.statement, 3, "Patients", "Most never received a chair."), E(.document, 2, "Delivery Receipts", "Signatures that don't match patients'."), E(.physical, 1, "Warehouse", "Three chairs in stock.")],
        defense: [E(.statement, 1, "Contractor", "{DL} says a contractor made deliveries."), E(.document, 1, "Staff Emails", "Emails about 'catching up on billing'.")],
        role: "Insurance investigator",
        exam: [.direct("What did you review in {D}'s billing records?", "\"Claims to insurers for $140,000 for twenty-two power wheelchairs. The claims list twenty-two chairs billed to patients.\""), .direct("What did the patients tell you when you contacted them?", "\"Most never received a chair. They told me plainly that they had never gotten one from {D}'s company.\""), .direct("What about the delivery receipts and the warehouse count?", "\"The receipts carried signatures that did not match the patients' signatures. The warehouse held only three chairs in stock.\""), .direct("Please describe your job as an insurance investigator.", "\"I investigate suspicious billing for an insurer. I review claims, contact patients, and inspect supplier records for chairs, beds, and other equipment.\""), .direct("How did you contact the patients?", "\"I called each of the patients on the claims and asked if they had received a power wheelchair. Most told me they never did and had no idea about the claim.\""), .direct("How many chairs were billed?", "\"Twenty-two. The warehouse only held three, so most of what was billed could not have been delivered.\""), .cross("{D} says employees handled the paperwork for those deliveries, doesn't {D.he}?", "\"Yes. And some deliveries were made by a contractor. I will agree that is possible, though I cannot confirm it.\""), .cross("Did {D} sign the claim forms that went to the insurers?", "\"{D.He} personally signed each claim form. The signature on every form is {D.his} own.\""), .cross("You cannot say who typed the claim forms, can you?", "\"No. I only know whose signature is on each one, and that is {D}'s.\""), .cross("Where did the insurers' payments go?", "\"Into an account that only {DL} controlled. Employees did not have access to it, and I cannot say who requested each deposit.\""), .cross("You did not see anyone sign the delivery receipts, did you?", "\"No. I compared the signatures to those on file for the patients. They did not match, and several patients said they never signed.\"")],
        theory: ("{D} billed insurers for chairs that were never delivered.", "An owner who left billing to staff."),
        allocution: "\"It was wrong from the start, and I knew it, or I should have. I left the paperwork to my employees and a contractor for deliveries, and I didn't check each one. I believed those chairs had been delivered. I'm sorry to every patient who waited, and I'll make it right.\"",
        truths: ("{DL} personally signed each claim form.", "{DL} deposited the insurers' payments into an account only {D.he} controlled."),
        defendant: [.direct("Did you bill for wheelchairs that were never delivered?", "\"No. I billed for chairs I believed were delivered. Employees handled the paperwork.\""), .direct("Who handled the delivery receipts?", "\"Employees, and a contractor for some deliveries. I did not check each one.\""), .direct("Did you sign the claim forms?", "\"Yes. I signed them. I trusted my staff, and I did not read every line.\""), .direct("What can you tell us about your equipment supply company?", "\"I own a company that supplies power wheelchairs and other equipment. I have a small staff, and a contractor makes some deliveries for us.\""), .direct("How did billing work in your company?", "\"Employees prepared the paperwork and I signed the claim forms. I was busy with sales and relied on staff to make sure the deliveries had happened.\""), .direct("What did you do when you learned of the insurer's questions?", "\"I told the investigator I would look into it. I asked employees about the receipts, and I learned there were problems with the signatures.\""), .cross("Most patients say they never received a chair. Are they all lying?", "\"No. I think some deliveries were missed. I did not know.\""), .cross("Only three chairs were in the warehouse, weren't they?", "\"Yes. I do not know where the others went.\""), .cross("The payments went into an account only you controlled, didn't they?", "\"Yes. It is my business account. I did not hide it.\""), .cross("The signatures on the delivery receipts did not match the patients' signatures on file, did they?", "\"That is what the investigator told me. I did not compare them myself, and I cannot explain the difference.\""), .cross("Emails among your staff talked about catching up on billing, didn't they?", "\"Yes. We were behind on paperwork. I did not understand that phrase meant billing for chairs that had not been delivered.\"")],
        openings: ("A medical equipment supplier owned by {D} billed insurers $140,000 for twenty-two power wheelchairs. Most patients say they never received a chair, delivery receipts bear mismatched signatures, and only three chairs were in the warehouse.", "The defense evidence will establish that employees handled the paperwork, that a contractor made some deliveries, and that {D} did not knowingly bill for chairs that were not delivered."),
        closings: ("Twenty-two chairs billed, most never delivered, mismatched signatures, three chairs in the warehouse, and every claim signed by {D}. The money went to an account only {DL} controlled.", "A busy owner who trusted employees and a contractor with the paperwork. The State must prove {D} knew the claims were false."),
        timeline: [(-365, "Billing begins."), (-120, "An insurer flags the claims."), (0, "The investigator calls the patients."), (14, "The warehouse is inspected."), (30, "{D} is interviewed.")],
        identified: "An insurer's claims review.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let liftingBackClaimV1 = SmallCases.make(
        key: "story.liftingBackClaim",
        category: .whiteCollar,
        headlines: ["Roofer on Disability Seen Hauling Shingles on Weekend Crew, Investigator Says", "Compensation File Shows $38,000 Paid in Eleven Months"],
        law: "insuranceFraud",
        threshold: 7,
        spec: "Presented a false workers' compensation claim to an insurer, {V}, totaling $38,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} collected $38,000 in workers' compensation after reporting a shoulder injury from a fall at a warehouse. An investigator hired by the insurer filmed {D.him} on {DATE} carrying bundles of shingles up a ladder on a weekend roofing job. Social media photos showed {D.him} on rooftops. {DL} says a friend let {D.him} sit and give directions and nothing more.",
        state: [E(.video, 3, "Surveillance", "{D} carries shingles up a ladder."), E(.document, 3, "Claim File", "$38,000 paid for a shoulder injury."), E(.digital, 2, "Social Media Photos", "{D} on a roof with a nail gun."), E(.statement, 1, "Doctor", "Restricted {D} from lifting.")],
        defense: [E(.statement, 1, "Directions Only", "{DL} says {D.he} only gave directions."), E(.document, 1, "Physical Therapy Notes", "Therapy visits twice a week.")],
        role: "Insurance investigator",
        exam: [.direct("What did {D}'s claim file show?", "\"$38,000 paid in workers' compensation for a shoulder injury from a fall at a warehouse. A doctor restricted {D} from lifting.\""), .direct("What did your surveillance film?", "\"It showed {DL} carrying bundles of shingles up a ladder on a weekend roofing job. I filmed it on the date in question.\""), .direct("What did the defendant's social media show?", "\"Photos of {DL} on rooftops, including one with a nail gun.\""), .direct("Tell us about your work as an insurance investigator.", "\"I investigate workers' compensation claims for an insurer. I review medical records, interview claimants, and use surveillance when a claim may be overstated.\""), .direct("How did you come to open an investigation into this claim?", "\"A tip came in to our fraud line that the claimant was working, so I was assigned to review the file and arrange surveillance.\""), .direct("How long did you watch?", "\"About four hours over two Saturdays, from a parked car across the street.\""), .cross("{D} says a friend let {D.him} sit and give directions, doesn't {D.he}?", "\"That is what {D.he} says. The video shows more than sitting.\""), .cross("Could the injury have been real?", "\"It could. A doctor documented a shoulder injury.\""), .cross("Did the defendant miss therapy appointments?", "\"Three of them. I will give you that.\""), .cross("How long was the work restriction?", "\"Six weeks. The note says no lifting over ten pounds until a follow-up visit.\""), .cross("The video was recorded on a single weekend day, wasn't it?", "\"Yes, one weekend day. I cannot tell you what {D.he} did on any other day.\"")],
        theory: ("{D} collected for an injury while working on roofs.", "A worker who only gave directions."),
        allocution: "\"My shoulder injury from that fall was real. I was supervising for a friend on that roof and wasn't doing the heavy work, but I should never have been up there while I was on a claim.\"",
        truths: ("{DL} told a coworker that the claim 'pays better than the warehouse'.", "{DL} missed three physical therapy appointments."),
        defendant: [.direct("Did you fake your shoulder injury?", "\"No. I hurt my shoulder in a fall at the warehouse. The injury was real.\""), .direct("Why were you on rooftops in photos?", "\"I was supervising for a friend. I did not do the heavy work. I should not have been up there.\""), .direct("Did you report the injury at work?", "\"Yes, the same day. The supervisor filled out a form, and I signed it.\""), .direct("What were you doing on the roofing job?", "\"A friend asked me to help on a weekend. I mostly sat and gave directions, though I may have carried a few bundles when the crew was short.\""), .direct("Why did you miss some therapy appointments?", "\"I had car trouble and some money problems. I did not think a missed visit meant much, but I understand now how it looks.\""), .direct("What did your doctor tell you about lifting after the injury?", "\"To avoid anything over ten pounds and to rest the shoulder. I tried, but bills piled up, and I took the roofing work against that advice.\""), .cross("You missed three therapy appointments, didn't you?", "\"Yes. I was busy. I should have gone.\""), .cross("You told a coworker the claim pays better than the warehouse, didn't you?", "\"I said something like that once, joking about the pay. I was not planning to deceive anyone, and I did not mean it.\""), .cross("The video shows you carrying shingles up a ladder, doesn't it?", "\"It does. I should not have done that with my restrictions. I did it once when my friend was short on help.\""), .cross("You kept collecting benefits after the weekend roofing job, didn't you?", "\"Yes. The checks kept coming, and I did not tell the insurer about the roofing work, which I should have done.\""), .cross("The photos show you on a roof with a nail gun, don't they?", "\"They do. I was on the roof for a few hours on a weekend. I should not have been, and I understand how it looks.\"")],
        openings: ("{D} collected $38,000 in workers' compensation for a shoulder injury, and an investigator filmed {DL} carrying bundles of shingles up a ladder on a weekend roofing job. Photos show {D.him} on rooftops with a nail gun.", "By the end of this trial, the proof will show that the injury was real, that a friend let {D} sit and give directions, and that {DL} carried only a few bundles."),
        closings: ("A shoulder injury claimed, $38,000 collected, and video of {D} carrying shingles up a ladder with photos on a roof. A doctor had restricted {D.him} from lifting.", "A real injury and a friend's roofing job. The State must prove {D} lied about the injury, and a few bundles on a good day are not that."),
        timeline: [(-330, "{D} reports the injury."), (-120, "The first doctor restriction."), (0, "The investigator films {D}."), (7, "The claim is reviewed."), (21, "{D} is interviewed.")],
        identified: "A surveillance video.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let stormRepairAdvanceV1 = SmallCases.make(
        key: "story.stormRepairAdvance",
        category: .whiteCollar,
        headlines: ["Fence Contractor Took Storm Repair Advances and Went Silent", "Posts Still Lying in Yards"],
        law: "falsePretenses100k",
        threshold: 8,
        spec: "Obtained over $100,000 by false pretenses from {V} and others, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After a windstorm, {D}, a fence contractor, took $112,000 in advances from nineteen homeowners and finished none on {DATE}. {DL} says lumber was scarce.",
        state: [E(.document, 3, "Advance Receipts", "$112,000 from nineteen homes."), E(.statement, 3, "Homeowner", "'He promised a week.'"), E(.document, 2, "License Check", "No license.")],
        defense: [E(.statement, 1, "Scarcity", "{DL} says lumber was scarce.")],
        role: "Homeowner",
        exam: [.direct("What did you pay {D} for after the windstorm?", "\"An advance for fence repairs. I was one of nineteen homeowners who paid advances totaling $112,000.\""), .direct("What did the defendant promise?", "\"{D} promised the work in a week, and nothing was ever started.\""), .direct("What did you learn about the defendant?", "\"No license was on record. {D.He} finished none of the fences, and the phone number was changed.\""), .direct("Walk us through what happened to your property in the storm.", "\"A windstorm knocked down much of the fence around my yard. I wanted it repaired before the winter, so I looked for a contractor right away.\""), .direct("Did you pay in advance?", "\"Yes, half up front. I gave a check, and it was cashed the next day.\""), .direct("What happened after you paid?", "\"Nothing was done. I called many times, and the calls went to voicemail. After a few weeks the number stopped working, and I never saw {D.him} again.\""), .cross("{D} says lumber was scarce, doesn't {D.he}?", "\"Yes. A supplier says lumber was scarce. I cannot argue.\""), .cross("Did the defendant finish any fences?", "\"I heard {DL} finished two. Mine was not one of them.\""), .cross("Did the defendant change phone numbers?", "\"Yes. The number I had stopped working.\""), .cross("Did the defendant ever tell you lumber was hard to get?", "\"Yes, once, at the start. I understood that, but I did not hear anything after that, and the work never began.\""), .cross("Did you know whether the defendant was licensed?", "\"No. I did not check. I learned later that {D.he} had no license on record, and I wish I had asked first.\"")],
        defenseRole: "Lumber supplier",
        defenseExam: [.direct("Was lumber scarce after the windstorm in your area?", "\"Yes. We had a shortage that lasted weeks. Everyone in town was waiting on orders, and I had a line of contractors.\""), .direct("Did {D} order lumber from your yard for the fence jobs?", "\"Some. {D} ordered part of what was needed and picked up a portion of the order a few days after the storm.\""), .direct("Did the defendant pay for the lumber that was ordered from you?", "\"Partly. {D.He} paid for some of it and still owed us for the rest when we last spoke.\""), .direct("Describe your lumber yard for the jury.", "\"I run a lumber yard that supplies contractors in the area. After the storm, everyone needed lumber at once, and we were short for weeks.\""), .direct("What did you see about the defendant's orders after the storm?", "\"{D.He} ordered part of what was needed and paid for those orders. The rest could not be filled because we did not have it in stock.\""), .direct("How long did the shortage last?", "\"Several weeks. Prices rose and deliveries were slow, and many contractors fell behind on their jobs. {D.He} was not the only one who struggled.\""), .cross("Did the defendant order enough lumber to build nineteen fences?", "\"No. Not nearly enough. The order was far smaller than nineteen fences would need, by a large margin.\""), .cross("Did the defendant come back to your yard for the rest of the order?", "\"No. I never saw {D.him} again after that pickup, and the rest of the order stayed on our shelves.\""), .cross("Did the defendant ever tell you about the advances taken from homeowners?", "\"No. I did not know about that. If I had, I would have asked {DF} some hard questions.\""), .cross("Did the defendant tell you how many homes were waiting on fences?", "\"No. {D.He} never said how many jobs there were, only that {D.he} needed lumber to get started.\""), .cross("Do you know what the defendant did with advances from homeowners?", "\"No. I only know about the orders at my yard. I do not know what {D.he} did with the money outside of those orders.\"")],
        theory: ("{D} took advances.", "Scarce lumber."),
        allocution: "\"I took those advances meaning to build every fence, and I was overwhelmed when lumber ran short. I was ashamed to tell people I couldn't deliver. I should have called each homeowner. I'll repay everyone as soon as I can.\"",
        truths: ("{DL} changed phone numbers.", "{DL} did finish two fences."),
