    static let sickPuppiesPapersV1 = SmallCases.make(
        key: "story.sickPuppiesPapers",
        category: .whiteCollar,
        headlines: ["Seller Delivered Sick Kittens With Forged Breed Papers", "Six Families, Six Vet Bills"],
        law: "falsePretenses",
        threshold: 7,
        spec: "Obtained property of {V} and others by false pretenses, $4,800, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} sold six kittens as pedigreed with forged papers on {DATE}. Four had severe infections. {DL} says the registry erred.",
        state: [E(.document, 3, "Registry Check", "No such registrations."), E(.statement, 3, "Vet", "'Infections in four.'"), E(.document, 2, "Sale Receipts", "$4,800 total.")],
        defense: [E(.statement, 1, "Registry", "{DL} says the registry erred.")],
        role: "Buyer",
        exam: [.direct("What did you buy from {D} in this sale?", "\"A kitten sold as pedigreed with papers. {D} sold six kittens in all, for $4,800 total, and I bought one of them.\""), .direct("What did the registry check show about the papers?", "\"No such registrations. The papers were not real, and the numbers on them did not match any record in the registry.\""), .direct("What did the vet find when examining the kittens?", "\"Infections in four of the six kittens. Mine was one of the sick ones, and it needed treatment for weeks.\""), .direct("Explain to the jury why you wanted a pedigreed kitten.", "\"I wanted a particular breed for my family and I was willing to pay for a good pedigree. The papers mattered to me because I planned to show the cat someday.\""), .direct("How did the sale go?", "\"I met {D.him} at {D.his} home and paid cash for the kitten. {D.He} handed me registration papers and said the kitten was healthy and from champion lines.\""), .direct("What happened to your kitten after you brought it home?", "\"Within days it was sneezing and refusing food. The vet found a serious infection, and I paid several hundred dollars in treatment.\""), .cross("{D} says the registry made an error, doesn't {D.he}?", "\"Yes. A registry clerk confirms a clerical delay around that time, and I will agree that such delays can happen.\""), .cross("Did {D} use the same registration number on more than one paper?", "\"Yes. The same fake number appears on several of the papers, which is part of why I doubted them.\""), .cross("Did the defendant offer a refund when the kitten turned out to be sick?", "\"Not at first. I had to ask more than once, and I did not receive any money back for weeks.\""), .cross("Did you check the papers before paying?", "\"No. I trusted the papers because they looked official. I did not call the registry until after my kitten fell ill.\""), .cross("Did the defendant ever tell you the registry might be slow?", "\"No. Nobody said anything about a delay. I was told the papers were complete and that the kitten was registered.\"")],
        defenseRole: "Registry clerk",
        defenseExam: [.direct("Does the registry sometimes have delays in processing papers?", "\"Sometimes. Registrations can take weeks to process, and the papers can lag well behind the litters themselves.\""), .direct("Was there a delay in this particular case at the registry?", "\"Unclear. We have a record of a clerical delay around that time, but I cannot say that it caused this.\""), .direct("Do breeders ever hand out papers before the registration is done?", "\"Some do. It is not allowed, but it happens, especially with small breeders who are in a hurry.\""), .direct("What can you tell us about your job at the registry?", "\"I process registrations for litters and breeders. I review applications, enter numbers, and respond to calls about papers that have not arrived.\""), .direct("What do you know about {D}'s application?", "\"We received an application, and a clerical delay held up processing for several weeks. During that period, no registration number had been issued for the litter.\""), .direct("Do breeders sometimes give buyers papers before registration is finished?", "\"Some do, though they should wait. A breeder who is impatient might hand out forms with a pending number, and that causes confusion later.\""), .cross("Does a delay at the registry create a fake registration number?", "\"No. A delay just means there is no number yet. It does not produce a false number on a form.\""), .cross("Did the number on these papers exist anywhere in your system?", "\"No. It did not exist in our system at all. We searched under it and found nothing.\""), .cross("Could someone have invented that number for the papers?", "\"Yes. It is possible. Anyone with a template could make up a number that looks real.\""), .cross("Did the registry ever issue the numbers on those six papers?", "\"No. The numbers on the papers were not ones the registry issued. I can only say that no such registrations exist in our system.\""), .cross("Did you tell the defendant to give buyers papers before the numbers were ready?", "\"No. We never told {D} to do that. A delay does not give anyone permission to hand out a number that was never assigned.\"")],
        theory: ("{D} sold sick kittens.", "A registry error."),
        allocution: "\"I did not forge those papers. The registry made an error, and I relied on it. The kittens looked healthy to me when I sold them, and I didn't know about any infections. I love animals and I never meant harm.\"",
        truths: ("{DL} reused the same fake number.", "The registry confirms a clerical delay."),
        defendant: [.direct("Did you forge the papers for the kittens you sold?", "\"No. The registry made an error, and I relied on it. I did not forge anything or make up a number.\""), .direct("Did you know the kittens were sick when you sold them?", "\"No. They looked healthy to me when I sold them. I did not know about any infections at that point.\""), .direct("Why was the same number on more than one set of papers?", "\"A mistake. I copied a number from one form to another and did not notice that I had repeated it.\""), .direct("What can you tell us about your breeding?", "\"I breed a few litters a year at home. I love the animals, I keep them clean, and I have sold kittens to families for years.\""), .direct("How did you get the papers for these six kittens?", "\"I applied through the registry and was told to expect them. I gave the buyers the paperwork I had, thinking registration was in process.\""), .direct("What did you do when a buyer called about a sick kitten?", "\"I offered to take it back and told the buyer I was sorry. I did not know the kittens had an infection when I sold them.\""), .cross("The registry says no such registrations exist, doesn't it?", "\"It does. I thought they were pending when I handed out the papers. I did not check on them.\""), .cross("Four of the six kittens had infections. Did you take them to a vet first?", "\"Not all of them. I should have had each one checked before selling, and I did not.\""), .cross("You reused a fake number on the papers. How is that a mistake?", "\"I pasted from a template. I should have been more careful, and I am sorry that I was not.\""), .cross("You used the same registration number on more than one set of papers, didn't you?", "\"Yes. I copied the number because I thought it applied to the whole litter. I know now that was a mistake.\""), .cross("You collected $4,800 for six kittens, didn't you?", "\"Yes. That was the price I asked. I believed they were pedigreed and healthy, and I did not intend to cheat anyone.\"")],
        openings: ("{D} sold six kittens as pedigreed with papers that turned out to be forged, and four had severe infections. The registry has no such registrations, and buyers paid $4,800.", "The defense witnesses will explain that the registry had a clerical delay, that {D} reused a number by mistake, and that {D.he} did not know the kittens were sick."),
        closings: ("Six kittens, fake registrations, the same fake number twice, and four sick animals. Buyers paid for pedigrees and got illness and paper.", "A clerical delay at the registry and a breeder who copied a number by mistake. The State must prove {D} meant to deceive buyers."),
        timeline: [(-30, "The litter."), (0, "The sales."), (5, "The kittens fall ill."), (14, "The check.")],
        identified: "A registry check.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let executorEstateSalesV1 = SmallCases.make(
        key: "story.executorEstateSales",
        category: .whiteCollar,
        headlines: ["Trustee Sold Family Land and Kept Proceeds From Siblings", "Closing Check Deposited Once"],
        law: "embezzlement",
        threshold: 7,
        spec: "Embezzled $64,000 belonging to {V}, a trust, by a person in a position of trust, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, the trustee of a family trust, sold a lot on {DATE} for $64,000 and deposited the check in a personal account. Siblings found no distributions. {DL} says debts used it.",
        state: [E(.document, 3, "Closing Statement", "$64,000 to the trustee."), E(.document, 3, "Trust Accounting", "No deposits."), E(.statement, 2, "Sibling", "'We never saw a dime.'")],
        defense: [E(.statement, 1, "Debts", "{DL} says debts used the money.")],
        role: "Sibling",
        exam: [.direct("What is your relationship to {DL}?", "\"{D} is my sibling and the trustee of our family trust. We were all beneficiaries.\""), .direct("What did {DL} do on {DATE}?", "\"Sold a lot owned by the trust for $64,000 and deposited the check into a personal account.\""), .direct("What does the closing statement show?", "\"$64,000 paid to the trustee. It names {DL} as the recipient of the funds.\""), .direct("What does the trust accounting show?", "\"No deposits. None of the $64,000 ever went into the trust account.\""), .direct("How did you find out?", "\"I asked for an accounting. We received nothing for months, and then learned of the sale from the county records.\""), .direct("Have you received any distributions?", "\"No. We never saw a dime. Not a check, not an explanation.\""), .cross("Does a trustee have debts to pay for the trust?", "\"Yes. A trustee can pay legitimate trust debts. But there should be records.\""), .cross("Did {DL} tell you about the sale?", "\"No. We heard from other sources. {D.He} did not tell us.\""), .cross("Does the trust owe taxes or fees?", "\"Possibly. I do not have the full picture. I only know what came in.\""), .cross("Did {DL} keep in touch?", "\"Sporadically. {D.He} said things were handled. We were never shown a record.\""), .cross("Did you ever agree to {DL} using the proceeds?", "\"No. We never agreed to that.\"")],
        defenseRole: "Trust attorney",
        defenseExam: [.direct("What is your role?", "\"I am the attorney who advises the trust. I helped with the sale paperwork.\""), .direct("Were there debts?", "\"Yes. The trust had debts and taxes that needed to be paid.\""), .direct("How large were they?", "\"Substantial. I can give you a range. Property taxes alone ran into the thousands.\""), .direct("Did {DL} ask you about using sale proceeds?", "\"Yes. {D} said bills had to be paid and I said a proper accounting was needed.\""), .direct("Did {DL} give you records?", "\"Some. Not all. I told {D.him} to keep every receipt.\""), .direct("Do you think {DL} meant to cheat the beneficiaries?", "\"I do not know. I saw a trustee who was overwhelmed and careless with paperwork.\""), .cross("Did you advise {DL} to deposit the check personally?", "\"No. I would have advised the trust account. I never approved a personal deposit.\""), .cross("Were the debts $64,000?", "\"No. They were nowhere near that. Part of the money cannot be explained.\""), .cross("Did you receive an accounting?", "\"I received partial records. I never got a full accounting.\""), .cross("Did you warn {DL} in writing?", "\"I sent an email. I did not follow up as much as That is on me.\""), .cross("Would you have approved paying personal bills?", "\"No. Never. I would never have approved paying personal bills.\"")],
        theory: ("{D} kept trust cash.", "Debts."),
        allocution: "\"The trust had debts that needed paying, and I sold the lot to raise the money. It was convenient to put it in my account, and I planned to move it into the trust, but I paid some bills first. I'm sorry to my siblings.\"",
        truths: ("{DL} bought a boat.", "Property taxes of $11,000 were paid from {DL}'s account."),
        defendant: [.direct("Why did you sell the lot?", "\"The trust had debts that needed to be paid. Selling the lot was the way to raise money.\""), .direct("Why did you deposit the check in your personal account?", "\"It was a mistake, and it was convenient. I planned to move it into the trust but I paid some bills first.\""), .direct("What did the $64,000 pay for?", "\"Debts of the trust and some expenses I covered. I did not keep every receipt.\""), .direct("Did you keep money for yourself?", "\"I paid myself back for out-of-pocket costs. I know I should have documented it.\""), .direct("Why did you not tell your siblings?", "\"I was embarrassed that I had not kept records. I planned to fix it. I let too much time pass.\""), .direct("How do you feel now?", "\"Terrible. I let my family down. I will do whatever I can to account for it.\""), .cross("You deposited trust money into your own account, didn't you?", "\"Yes. That was wrong. I should have used the trust account.\""), .cross("You paid your own bills from the money, didn't you?", "\"Some of them. I told myself it was repayment. I know that is not the same.\""), .cross("Your siblings were never told, were they?", "\"No. They were not. I should have told them.\""), .cross("You have no accounting, do you?", "\"Not a complete one. I have bits and pieces.\""), .cross("The trust got none of the $64,000, didn't it?", "\"Directly, no. I used it to pay trust debts, but I cannot prove each.\"")],
        openings: ("{D}, the trustee of a family trust, sold a lot for $64,000, deposited the check in a personal account, and none of it reached the beneficiaries. {D.his} own siblings never received a distribution. The State will show the closing statement and the accounting.", "A trustee with real debts to pay and poor records. {D} says debts used the money, and the trust's own lawyer will confirm there were bills to cover."),
        closings: ("A lot sold for $64,000, the check deposited in {D}'s personal account, no deposits to the trust, and no distribution to anyone. The beneficiaries never saw a dime.", "{D} used proceeds to cover trust debts and kept poor records. The State has not proved {DL} meant to keep the beneficiaries' money."),
        timeline: [(-90, "The trust opens."), (0, "Month 3: the sale."), (0, "Month 6: siblings ask."), (1, "{DL} is charged.")],
        identified: "A closing statement.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .divided,
        impact: "{V.He} left us the land. It had been in our family for four generations, and we'd planned to hold onto it for our kids. When we asked about distributions, we found it had been sold and the money was gone. The land was the last thing our father gave us.",
        doctrines: ["burdenOfProof"])

    static let tuitionCheckBookkeeperV1 = SmallCases.make(
        key: "story.tuitionCheckBookkeeper",
        category: .whiteCollar,
        headlines: ["Dance Studio Bookkeeper Deposited Recital Fee Checks Into Personal Account", "Parents' Cancelled Checks Show a Different Endorsement"],
        law: "embezzlement",
        threshold: 7,
        spec: "Embezzled $18,500 belonging to {V}, a dance studio, by a person in a position of trust, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A dance studio's bookkeeper, {D}, deposited recital fee and tuition checks from parents into a personal account for ten months. The total was $18,500. Parents' cancelled checks showed a personal endorsement, not the studio's stamp. The studio owner found the gap when a parent asked for a receipt. {DL} says the bank mislabeled the studio's account number.",
        state: [E(.document, 3, "Deposit Slips", "Checks deposited into {D}'s personal account."), E(.document, 3, "Cancelled Checks", "Parents' checks with a personal endorsement."), E(.document, 2, "Ledger", "Payments recorded but never deposited.")],
        defense: [E(.statement, 1, "Bank Mislabel", "{DL} says the bank mislabeled the account."), E(.document, 1, "Bank Letter", "A letter about a processing error.")],
        role: "Studio owner",
        exam: [.direct("What did you discover about your studio's bookkeeping?", "\"Parents' recital fees and tuition checks were deposited into a personal account for ten months, totaling $18,500.\""), .direct("How did you find the gap?", "\"A parent asked for a receipt, and I could not match it. The ledger showed payments recorded but never deposited.\""), .direct("What did the cancelled checks show?", "\"A personal endorsement, not the studio's stamp. The deposit slips show {D}'s personal account.\""), .direct("What can you tell us about your dance studio?", "\"I own a dance studio with about two hundred students. We teach children and teens, and we hold a recital each spring that families look forward to.\""), .direct("What did {D} do for the studio?", "\"{D.He} was my bookkeeper. {D.He} collected tuition and recital fee checks, made deposits, and kept the ledger. I trusted {D.him} with the money for ten months.\""), .direct("What did the bank slips show when you pulled them?", "\"Parents' checks were deposited into a personal account in {D.his} name. The total was $18,500 over ten months, and the studio account never received them.\""), .cross("{D} says the bank mislabeled the studio's account number, doesn't {D.he}?", "\"Yes. A bank error is possible. But the account opened three weeks before the first check.\""), .cross("Did {D} hide the gap?", "\"The ledger entries were adjusted. That is what I found.\""), .cross("Did the defendant tell you about the deposits?", "\"No. {D.He} never told me.\""), .cross("Did the ledger show that parents had paid?", "\"Yes. The ledger recorded the payments. But the deposits did not match, and some entries had been adjusted so the gap would not show.\""), .cross("Did the defendant tell you about a bank error?", "\"Yes. {D.He} said the bank mislabeled the account and showed me a letter about a processing error. I do not think that explains the personal endorsement.\"")],
        theory: ("{D} deposited the studio's checks into {D.his} own account.", "A bookkeeper blamed a bank error."),
        allocution: "\"The bank mislabeled the studio's account number, and some checks went into mine by mistake. I didn't plan this. I should have caught it much sooner and told the owner. I'm sorry to the families.\"",
        truths: ("{DL} had opened the personal account three weeks before the first check.", "{DL} adjusted the ledger entries to hide the gap."),
        defendant: [.direct("Did you deposit parents' checks into your personal account?", "\"No. The bank mislabeled the studio's account number, and the checks went to my account by mistake.\""), .direct("When did you open the personal account?", "\"Three weeks before the first check. It was for my own use. I did not plan this.\""), .direct("Why did you adjust the ledger entries?", "\"I was trying to make the books balance. I should not have touched them.\""), .direct("What can you tell us about your job at the studio?", "\"I worked as the bookkeeper for several years. I collected checks, made deposits, and kept the books, and I got along well with the families.\""), .direct("What do you say happened with the bank?", "\"The bank mislabeled the studio's account number. I trusted what the bank told me, and I did not realize the checks were going into my personal account.\""), .direct("What did the bank's letter say?", "\"It described a processing error on the account. I showed the letter to the owner when questions began, because I thought it explained what had happened.\""), .cross("Ten months of deposits and you never noticed?", "\"I did not look at my account closely. I know I should have.\""), .cross("The cancelled checks have a personal endorsement. Whose?", "\"Mine. I endorsed them. I did not read the account.\""), .cross("$18,500 is a lot of money not to notice, isn't it?", "\"It is. I was careless. I truly am sorry.\""), .cross("You changed ledger entries, didn't you?", "\"Yes. I changed some entries when I saw the numbers did not match. I should have reported it, and I did not want to cause alarm.\""), .cross("The checks carried your personal endorsement, didn't they?", "\"I endorsed checks the way I always had. I did not think about which account they went to, and that was careless.\"")],
        openings: ("A dance studio's bookkeeper, {D}, deposited parents' recital fee and tuition checks into a personal account for ten months, totaling $18,500. The ledger showed the payments recorded but never deposited.", "The defense case is that the bank mislabeled the studio's account number and that {D} did not notice the deposits going into the wrong account."),
        closings: ("Ten months, $18,500, a personal account opened three weeks before the first check, and ledger entries that hid the gap. {D} took the studio's money.", "A bank mislabel and a bookkeeper who did not read a statement. The State must prove {D} knew and meant to take the money."),
        timeline: [(-300, "{D} opens a personal account."), (-290, "The first deposit."), (0, "A parent asks for a receipt."), (1, "The owner reviews the ledger."), (14, "The bank pulls the slips.")],
        identified: "A cancelled check.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let unionTreasurerChecksV1 = SmallCases.make(
        key: "story.unionTreasurerChecks",
        category: .whiteCollar,
        headlines: ["Local Treasurer Wrote Himself Reimbursements for Trips Never Taken", "$96,000 Over Three Years"],
