        defense: [E(.statement, 1, "Approved", "{DL} says the board approved travel.")],
        role: "Union president",
        exam: [.direct("What did you find when you reviewed the union's finances?", "\"Reimbursement checks payable to {D}, the treasurer, totaling $110,000 over three years, and no trips booked to match.\""), .direct("What do the travel records show about those reimbursements?", "\"No trips booked at all. Nothing in the records supports the reimbursements, and no tickets or bookings were ever made.\""), .direct("What did a member tell you about these payments?", "\"'No one approved it.' The member told me that the board never signed off on any of those payments.\""), .direct("Tell us about your role as union president.", "\"I lead a local union with several hundred members. I run meetings, bargain contracts, and watch the finances alongside the board and the treasurer.\""), .direct("What did the audit show about the checks?", "\"Over three years, checks totaling $110,000 were written to {D.him}, the treasurer, as reimbursements. I found no travel records that supported any of them.\""), .direct("What did members tell you about the approvals?", "\"Members said no one approved those trips. At meetings, we heard about general travel for union business, but never about trips of this size.\""), .cross("{D} says the board approved travel, doesn't {D.he}?", "\"Board minutes mention travel in general terms. I will agree with that, but they do not list any amounts.\""), .cross("Are there receipts for the money that was paid to the defendant?", "\"For some of it. For about $80,000, no receipts exist, and {D.he} has not been able to produce any.\""), .cross("Did the board approve some of the trips that were taken?", "\"Some, yes. But not $110,000 worth, and not trips that no record shows were ever booked.\""), .cross("Who made the motion for travel?", "\"The treasurer. The minutes show the motion and the vote.\""), .cross("Which payments had no receipts?", "\"Several large reimbursements to the defendant. We never found paperwork for them.\"")],
        defenseRole: "Board member",
